# -- EvalPlus on the served route (Lane C) --
EVALPLUS_PIN = "0.3.1"
EVALPLUS_TASK_PREFIX = "evalplus/"
#: Same framework pin as the HF path's ``humaneval_plus`` rows
#: (``evalplus_runner.eval_results_to_rows``: ``evalplus-0.3.1``); the task
#: NAME (prefix) and the ``engine`` column keep the two paths apart.
EVALPLUS_TASK_VERSION = f"evalplus-{EVALPLUS_PIN}"
EVALPLUS_DATASETS: Tuple[str, ...] = ("humaneval", "mbpp")
#: The thinking-ON true readout (P12): no assistant prefill, first fenced
#: python block extracted — a DISTINCT task name, never a metric variant.
OPEN_VARIANT_SUFFIX = ":open"
EXPECTED_HUMANEVAL_PLUS_N = 164
EXPECTED_MBPP_PLUS_N = 378
#: PW12 (E19, NEW High): ``pass@1_plus`` had TWO definitions under one metric
#: identity — evalplus 0.3.1's own headline (a sample passes the plus set
#: only when it passes the BASE tests AND the plus tests, ``evaluate.py``'s
#: ``new_correct``; every converter since PW10) and the earlier
#: ``plus_status`` alone (the retained 618f9dd stores, the exec wave's
#: converter until PW12) — both emitting ``pass@1_plus`` / ``acc`` under
#: ``evalplus-0.3.1``. The definition is now NAMED wherever the number
#: travels: ``extra_json[metric_def]`` on every ``pass@1_plus`` and gating
#: ``acc`` row, and ``metric_def`` in the task's summary payload
#: (:data:`SUMMARY_PAYLOAD_FIELDS`). A payload or row WITHOUT the field was
#: written under the old definition: ``cell_controls.load_controls_summaries``
#: stamps such an EvalPlus entry :data:`EVALPLUS_PLUS_DEF_PLUS_ONLY` at load
#: (said on stdout) and ``comparison_inputs`` refuses to pair two payloads
#: whose definitions differ. ``task_version`` stays ``evalplus-0.3.1``: the
#: framework pin is what it says, and the definition rides beside it.
EVALPLUS_METRIC_DEF_FIELD = "metric_def"
EVALPLUS_PLUS_DEF_BASE_AND_PLUS = "base_and_plus"
EVALPLUS_PLUS_DEF_PLUS_ONLY = "plus_only"
EVALPLUS_PLUS_DEFS: Tuple[str, ...] = (EVALPLUS_PLUS_DEF_BASE_AND_PLUS, EVALPLUS_PLUS_DEF_PLUS_ONLY)
#: PW13 (E21 M1): the definition is IDENTITY-BEARING on the ROWS — the row
#: ``task_version`` names it: ``evalplus-0.3.1+base_and_plus`` for every row a
#: converter of this tree writes (:func:`evalplus_row_task_version`), while the
#: bare framework pin ``evalplus-0.3.1`` is the literal the RETAINED plus-only
#: rows (the 618f9dd stores) carry and is never written again
#: (:func:`evalplus_row_metric_def` reads it as :data:`EVALPLUS_PLUS_DEF_PLUS_ONLY`).
#: Chosen over hashing the definition into ``harness_config_hash`` (which would
#: re-key EVERY store of every task for a change that concerns four EvalPlus
#: tasks, orphaning in-flight pass-1 stores) and over a fifth merge-source
#: field (which would change the shape of every recorded source, history and
#: witness): the row column is what row consumers already key on —
#: ``stats.calibrate`` refuses a task with mixed ``task_version`` values and
#: ``eval_config_digest`` drifts on it — so two definitions can no longer be
#: pooled by a consumer that never reads ``extra_json``. :data:`EVALPLUS_TASK_VERSION`
#: itself stays the framework pin (the summary payload's ``framework``, the
#: client-lock check). ``pass@1_base`` rows carry the same task version as
#: their siblings: a task's rows share ONE instrument version (the converter
#: changed), and calibration refuses a task under two.
EVALPLUS_TASK_VERSION_DEF_SEP = "+"


def evalplus_row_task_version(metric_def: str, *, pin: str = EVALPLUS_TASK_VERSION) -> str:
    """The ``task_version`` an EvalPlus ROW carries under ``metric_def`` —
    ``<pin>+<definition>`` (``evalplus-0.3.1+base_and_plus``), except that
    :data:`EVALPLUS_PLUS_DEF_PLUS_ONLY` maps to the bare ``pin``: that is the
    literal the retained plus-only rows already carry, so the two readings
    round-trip and no retained row needs relabelling. A definition outside
    :data:`EVALPLUS_PLUS_DEFS` refuses."""
    if metric_def not in EVALPLUS_PLUS_DEFS:
        raise ValueError(
            f"metric_def {metric_def!r} is not a pass@1_plus definition this repo names "
            f"({list(EVALPLUS_PLUS_DEFS)}); refusing to mint a task_version for it (PW13)")
    if metric_def == EVALPLUS_PLUS_DEF_PLUS_ONLY:
        return pin
    return f"{pin}{EVALPLUS_TASK_VERSION_DEF_SEP}{metric_def}"


def evalplus_row_metric_def(task_version: str, *, pin: str = EVALPLUS_TASK_VERSION) -> str:
    """The inverse of :func:`evalplus_row_task_version`: the bare ``pin`` is
    the retained plus-only rows' literal (:data:`EVALPLUS_PLUS_DEF_PLUS_ONLY`);
    ``<pin>+<definition>`` names its definition; anything else — another
    framework pin, a definition this repo does not name — refuses rather than
    being read as either."""
    if task_version == pin:
        return EVALPLUS_PLUS_DEF_PLUS_ONLY
    prefix = f"{pin}{EVALPLUS_TASK_VERSION_DEF_SEP}"
    if isinstance(task_version, str) and task_version.startswith(prefix):
        metric_def = task_version[len(prefix):]
        if metric_def in EVALPLUS_PLUS_DEFS:
            return metric_def
    raise ValueError(
        f"task_version {task_version!r} is neither the framework pin {pin!r} (the retained "
        f"plus-only rows) nor {prefix}<definition> with a definition in {list(EVALPLUS_PLUS_DEFS)}; "
        "refusing to read a pass@1_plus definition off it (PW13)")


def evalplus_metric_def(key: str, payload: object) -> Optional[str]:
    """The ``pass@1_plus`` DEFINITION an EvalPlus summary payload was computed
    under: the one it names, or :data:`EVALPLUS_PLUS_DEF_PLUS_ONLY` when it
    names none (every converter before PW12; the retained 618f9dd stores) —
    ``None`` for an entry that is not an EvalPlus task
    (:data:`EVALPLUS_TASKS`) or not a mapping. A definition outside
    :data:`EVALPLUS_PLUS_DEFS` refuses: not a reading this repo makes."""
    if key not in EVALPLUS_TASKS or not isinstance(payload, Mapping):
        return None
    have = payload.get(EVALPLUS_METRIC_DEF_FIELD)
    if have is None:
        return EVALPLUS_PLUS_DEF_PLUS_ONLY
    if have not in EVALPLUS_PLUS_DEFS:
        raise ValueError(
            f"{key!r} says {EVALPLUS_METRIC_DEF_FIELD}={have!r}; the definitions this repo names "
            f"are {list(EVALPLUS_PLUS_DEFS)} (PW12)")
    return have


def with_evalplus_metric_def(key: str, payload: Mapping[str, object]) -> Dict[str, object]:
    """``payload`` with its ``metric_def`` made EXPLICIT for an EvalPlus entry
    (:func:`evalplus_metric_def`; a copy) — unchanged for every other entry.
    The ONE normalization every comparison of EvalPlus payloads goes through
    (PW13 / E21 M1): the writer (``cell_controls.write_controls_summary``,
    which also WRITES the stamped payload), the loader
    (``load_controls_summaries``) and the equal-witness planner
    (``completion.equal_witness_plan``), so "absent" can never compare
    differently in one place than another."""
    metric_def = evalplus_metric_def(key, payload)
    if metric_def is None or payload.get(EVALPLUS_METRIC_DEF_FIELD) == metric_def:
        return dict(payload)
    return {**payload, EVALPLUS_METRIC_DEF_FIELD: metric_def}


#: PW14 (E22 H1): the metrics whose rows carry ``extra_json.metric_def`` — the
#: ``pass@1_plus`` headline and the gating ``acc`` that equals it (``pass@1_base``
#: carries none: its definition never changed). The evalplus converter's
#: ``_DEFINED_METRICS`` and the stats readers' metadata scan are both this tuple.
EVALPLUS_DEFINED_METRICS: Tuple[str, ...] = ("pass@1_plus", "acc")
#: The exec wave's HF-path rows suffix the version with the dataset hash
#: (``evalplus-0.3.1+base_and_plus/<hash>``); the definition grammar applies to
#: the part BEFORE this separator and the hash rides through unchanged.
EVALPLUS_TASK_VERSION_HASH_SEP = "/"


def is_evalplus_task_version(task_version: object, *, pin: str = EVALPLUS_TASK_VERSION) -> bool:
    """True iff ``task_version`` is a row version of THIS framework pin — the
    bare ``pin`` or ``<pin>+<definition>``, optionally followed by
    ``/<dataset hash>`` (the exec wave's HF-path rows). Another framework pin
    (``evalplus-0.4.0``) is another instrument and is left alone."""
    if not isinstance(task_version, str):
        return False
    head = task_version.split(EVALPLUS_TASK_VERSION_HASH_SEP, 1)[0]
    return head == pin or head.startswith(f"{pin}{EVALPLUS_TASK_VERSION_DEF_SEP}")


def evalplus_effective_task_version(task_version: str, metric_defs, *,
                                    pin: str = EVALPLUS_TASK_VERSION) -> str:
    """PW14 (E22 H1): the version an EvalPlus task's rows are EFFECTIVELY
    under — the ``task_version`` column read TOGETHER with the ``metric_def``
    metadata of its ``pass@1_plus`` / ``acc`` rows (``metric_defs``: the set
    of ``extra_json.metric_def`` values seen on those rows, ``None`` for
    absent). The bare pin alone is not proof of ``plus_only``: the code between
    e7c0da4 and 765251a (PW12) computed base AND plus and still emitted the
    bare version, so a consumer that pools on the column alone would pool an
    old plus-only calibration with a PW12 base-and-plus run. Rules:

    * bare version + every row absent (or every row ``plus_only``) → the bare
      pin (= :data:`EVALPLUS_PLUS_DEF_PLUS_ONLY`, the retained rows);
    * bare version + every row explicitly ``base_and_plus`` → the suffixed
      version ``<pin>+base_and_plus`` (the same instrument as rows written
      under it — pooled with them, never with plus-only rows);
    * suffixed version + absent or agreeing metadata → itself;
    * MIXED metadata within the group (some rows named, some absent; two
      names) or metadata CONTRADICTING a suffixed version → refuse
      (``ValueError``, naming the version and the values) — a group two
      converters wrote is not one instrument.

    A trailing ``/<dataset hash>`` (the exec wave's HF-path rows) rides through
    unchanged; a version that is not this pin's grammar refuses."""
    if not isinstance(task_version, str) or not is_evalplus_task_version(task_version, pin=pin):
        raise ValueError(
            f"task_version {task_version!r} is not a row version of the framework pin {pin!r} "
            f"(bare, or {pin}{EVALPLUS_TASK_VERSION_DEF_SEP}<definition>, optionally "
            f"{EVALPLUS_TASK_VERSION_HASH_SEP}<dataset hash>); refusing to derive an effective "
            "version for it (PW14)")
    head, sep, tail = task_version.partition(EVALPLUS_TASK_VERSION_HASH_SEP)
    declared = evalplus_row_metric_def(head, pin=pin)          # bare = plus_only; suffixed names it
    named = set(metric_defs)
    if len(named) > 1:
        raise ValueError(
            f"task_version {task_version!r}: its {list(EVALPLUS_DEFINED_METRICS)} rows carry MIXED "
            f"{EVALPLUS_METRIC_DEF_FIELD} metadata {sorted(named, key=str)} (None = absent) — a group "
            "two converters wrote is not one instrument; refusing to pool it (PW14 / E22 H1)")
    explicit = next(iter(named), None)
    if explicit is not None and explicit not in EVALPLUS_PLUS_DEFS:
        raise ValueError(
            f"task_version {task_version!r}: its rows say {EVALPLUS_METRIC_DEF_FIELD}={explicit!r}; "
            f"the definitions this repo names are {list(EVALPLUS_PLUS_DEFS)} (PW14)")
    if explicit is None or explicit == declared:
        effective = declared
    elif head == pin:
        effective = explicit                                    # bare + explicit base_and_plus (PW12-era)
    else:
        raise ValueError(
            f"task_version {task_version!r} names the {declared!r} definition but its rows say "
            f"{EVALPLUS_METRIC_DEF_FIELD}={explicit!r} — a contradictory group; refusing to read it "
            "as either (PW14 / E22 H1)")
    return f"{evalplus_row_task_version(effective, pin=pin)}{sep}{tail}"


def evalplus_task(dataset: str, *, open_variant: bool = False) -> str:
    """``evalplus/humaneval_plus`` / ``evalplus/mbpp_plus`` (+ ``:open``);
    ``item_id`` = the EvalPlus task id (``HumanEval/<n>`` / ``Mbpp/<n>``)."""
    if dataset not in EVALPLUS_DATASETS:
        raise ControlNameError(f"{dataset!r} is not an evalplus dataset: {list(EVALPLUS_DATASETS)}")
    return f"{EVALPLUS_TASK_PREFIX}{dataset}_plus{OPEN_VARIANT_SUFFIX if open_variant else ''}"


EVALPLUS_TASKS: Tuple[str, ...] = tuple(
    evalplus_task(d, open_variant=o) for d in EVALPLUS_DATASETS for o in (False, True))
#: Which EvalPlus dataset each EvalPlus control atom runs
#: (``evalplus_runner.run_served(datasets=...)``; PC9) — pinned against
#: :data:`TASKS_OF_CONTROL` by test so the two can never disagree.
EVALPLUS_DATASET_OF_CONTROL: Mapping[str, str] = {
    CONTROL_HUMANEVAL_PLUS: "humaneval", CONTROL_MBPP_PLUS: "mbpp"}

#: Every tinycap row task name.
