THINKING_SMOKE_COMPLETIONS_DIR = "data/tinycap/thinking_smoke"
#: llama-paper-rows (P8): where the NO-SWITCH diagnostic smoke's real completions
#: are committed, per family (``<dir>/<family>/smoke_completions.jsonl`` +
#: ``smoke_report.json`` + ``usage_ledger.jsonl``) — what
#: ``tests/test_no_switch_smoke_real_completions.py`` reads to certify a
#: switch-less family's render fact (header ids equal by tuple through the live
#: ``/v1/tokenize`` with no kwargs, every stamp ``unspecified``, zero think tags,
#: zero reasoning channel, every wire body free of ``chat_template_kwargs``); a
#: ``certified`` no-switch fact whose completions are not committed there fails
#: that test by name
NO_SWITCH_SMOKE_COMPLETIONS_DIR = "data/tinycap/no_switch_smoke"


class RenderFact(NamedTuple):
    """One family's VERIFIED thinking render fact."""

    family: str
    #: the appended assistant header ids under each arm (tuple equality, never width)
    off_ids: Tuple[int, ...]
    on_ids: Tuple[int, ...]
    #: does the ON PROMPT open the think block (implicit-open)?
    prompt_opens_think_on: bool
    #: the think delimiters as TEXT and as ids (ids None where the family has
    #: no atomic tag token — gemma's channel markers are parser-separated)
    think_open: str
    think_close: str
    think_open_id: Optional[int]
    think_close_id: Optional[int]
    #: the harness-side split mode (``THINK_SPLIT_MODES``) that IS this family's
    #: parser where no server parser exists; ``None`` = no verified rule yet
    split_mode: Optional[str]
    #: the server reasoning parser (``REASONING_PARSER_BY_FAMILY``), or None
    server_parser: Optional[str]
    #: ``candidate`` | ``certified`` (:data:`RENDER_EVIDENCE_STATUSES`)
    evidence_status: str
    #: prose: where the ids and the mode were measured / certified
    evidence: str
    #: PR-A (P7): whether the family's template carries a thinking SWITCH at all — False for a
    #: no-thinking-channel family, whose runs are the :data:`CERT_CLASS_NO_SWITCH` class (:func:`cert_class_for`)
    thinking_switch: bool = True

    def as_dict(self) -> Dict[str, object]:
        return {"family": self.family, "off_ids": list(self.off_ids), "on_ids": list(self.on_ids),
                "prompt_opens_think_on": bool(self.prompt_opens_think_on),
                "think_open": self.think_open, "think_close": self.think_close,
                "think_open_id": self.think_open_id, "think_close_id": self.think_close_id,
                "split_mode": self.split_mode, "server_parser": self.server_parser,
                "evidence_status": self.evidence_status, "evidence": self.evidence,
                "thinking_switch": bool(self.thinking_switch)}

    @property
    def header_moves(self) -> bool:
        """Whether the header MOVES between arms — by ID TUPLE, never width."""
        return tuple(self.off_ids) != tuple(self.on_ids)


