class RenderFactUnverified(ValueError):
    """A thinking-ON run named a family with no render fact, a fact with no
    split mode, or a fact whose evidence is not ``certified`` where production
    generation requires it."""


def render_fact_for(family: object) -> Optional[RenderFact]:
    """The family's :class:`RenderFact`, or ``None`` for a family with none."""
    return FAMILY_RENDER_FACTS.get(str(family)) if family is not None else None


def render_fact_certified(fact: Optional[RenderFact]) -> bool:
    """True iff ``fact`` exists, names a split mode and is ``certified``."""
    return (fact is not None and fact.split_mode in THINK_SPLIT_MODES
            and fact.evidence_status == RENDER_EVIDENCE_CERTIFIED)


def render_fact_refusal(family: object, *, require_certified: bool = True) -> Optional[str]:
    """Why a thinking-ON run of ``family`` cannot be planned on its render
    fact — ``None`` when it can: no fact / no split mode -> "render fact
    unverified"; a ``candidate`` fact under ``require_certified`` (production)
    -> "render fact not certified" naming the gate (G-PARSER)."""
    fact = render_fact_for(family)
    if fact is None or fact.split_mode not in THINK_SPLIT_MODES:
        return (f"family {family!r}: render fact unverified — FAMILY_RENDER_FACTS carries "
                + ("no entry" if fact is None else "no split mode")
                + " for it, so what the model renders and emits under thinking-ON is unknown; "
                "refusing rather than guessing a split (plan §4.3 item 1)")
    if require_certified and fact.evidence_status != RENDER_EVIDENCE_CERTIFIED:
        return (f"family {family!r}: render fact not certified — evidence_status is "
                f"{fact.evidence_status!r}, and production generation requires "
                f"{RENDER_EVIDENCE_CERTIFIED!r} (the real-completion parser certification G-PARSER, "
                f"plan §5.3; D12 P1-7, D17 P1-b). {fact.evidence}")
    return None


def check_render_fact_certified(family: object, *, require_certified: bool = True) -> RenderFact:
    """The PREFLIGHT seam the cluster dry run (`--stage prod`) and the driver
    share: the family's fact, or :class:`RenderFactUnverified` naming why it
    cannot carry production traffic (:func:`render_fact_refusal`)."""
    why = render_fact_refusal(family, require_certified=require_certified)
    if why is not None:
        raise RenderFactUnverified(why)
    fact = render_fact_for(family)
    assert fact is not None
    return fact


# --------------------------------------------------------------------------- #
# the per-op HEADER-LOCATED predicate on SERVED positions                       #
# --------------------------------------------------------------------------- #

#: the served position modes whose mask is LOCATED against the assistant
#: header (``lens_adapters.RESPONSE_MASK_MODES``): the proxy's own tuple, by
#: reference (``proxy.HEADER_LOCATED_MODES``; the torch-free copy)
HEADER_LOCATED_MODES: Tuple[str, ...] = tuple(_proxy.HEADER_LOCATED_MODES)
#: the routing-table / ``endpoint.json`` / ``/v1/models.petri_proxy`` key of the
#: per-cell SERVED-positions map Evals' exporter stamps:
#: ``{harness cell id: [served mode, ...]}``
LENS_SERVED_POSITIONS_KEY: str = _proxy.LENS_SERVED_POSITIONS_KEY
#: the ENGINE-NEUTRAL served-positions map beside it (``proxy.SERVED_POSITIONS_KEY``;
#: native-positions-resolve): the lens legs' stated modes AND every lora route's
#: attested mode, ``{harness cell id: [mode, ...]}``, read FIRST by the served
#: driver and by the GSM8K reader's standup-record resolution; absent on an
#: older record (the lens map / the routes' own attestation are then read)
SERVED_POSITIONS_KEY: str = _proxy.SERVED_POSITIONS_KEY


def header_located(served_positions: object) -> bool:
    """Whether a cell's SERVED mask is header-located — the declaration
    predicate: True iff ANY served op's mode is in
    :data:`HEADER_LOCATED_MODES`; UNKNOWN reads True (fail closed, as the
    proxy reads it). ``served_positions`` is one of: the routing table's
    ``lens_served_positions[cell]`` value (a list of modes), one mode string,
    a RESOLVED SPEC mapping (unwrapped through the ONE unwrapper
    ``defense_cells.served_positions_of`` — a stacked spec's OBJECT leg), or
    ``None`` / an absent cell (-> True). A mode outside the served vocabulary
    (``proxy.POSITION_MODES``) reads True too: a fact the gate cannot
    classify is never read as "not header-located"."""
    if served_positions is None:
        return True
    if isinstance(served_positions, Mapping):
        dc, _ra = _cell_grammar()
        mode = dc.served_positions_of(served_positions)
        return header_located(mode)
    modes: List[object]
    if isinstance(served_positions, str):
        modes = [served_positions]
    elif isinstance(served_positions, (list, tuple)):
        modes = list(served_positions)
    else:
        return True
    if not modes:
        return True
    for m in modes:
        if not isinstance(m, str) or m not in _proxy.POSITION_MODES:
            return True
    return any(m in HEADER_LOCATED_MODES for m in modes)


#: the predicate under a name no keyword parameter shadows (several checkers
#: take a ``header_located: bool`` argument and still need to CALL the predicate)
_is_header_located = header_located


def served_positions_of_cell(doc: object, cell: str) -> Optional[List[str]]:
    """``doc[lens_served_positions][cell]`` as a list of modes, ``None`` when
    the document, the map or the cell is absent (the reader then decides
    header-located, fail closed). ``doc`` is the routing table, ``endpoint.json``
    or the ``/v1/models`` ``petri_proxy`` block."""
    if not isinstance(doc, Mapping):
        return None
    table = doc.get(LENS_SERVED_POSITIONS_KEY)
    if not isinstance(table, Mapping) or cell not in table:
        return None
    return _served_modes(table[cell])


#: the refusal, by name, of a RESOLVED served mode the gate cannot classify: a native-vocabulary mode
#: (``defense_cells.NATIVE_POSITION_MODES``: ``prompt_last`` / ``prefill_all``) outside the lens vocabulary
#: (``proxy.POSITION_MODES``), which :func:`header_located` would otherwise read as header-located, fail closed — a
#: WRONG POSITIVE stamp, the null bug one vocabulary over. Both read sites (the served driver's standup lookup and
#: the GSM8K reader's standup-record resolution) refuse it instead of deriving a header fact from it; whether such a
#: mode locates a header is a stage-2 design decision, kept visible by the refusal. ``all`` and
#: ``response`` are shared by both vocabularies and read exactly as before.
NATIVE_POSITION_MODE_UNCLASSIFIED = "NATIVE_POSITION_MODE_UNCLASSIFIED"


def unclassified_native_modes(modes: object) -> List[str]:
    """The modes among ``modes`` (one mode or a list) that are in the native vocabulary and NOT in the lens one —
    the ones :func:`header_located` cannot classify and would read as header-located. Empty when every mode is
    classifiable (or ``modes`` is not a served-positions value at all: that shape is refused elsewhere)."""
    listed = _served_modes(modes) or []
    return [m for m in listed if m in _proxy.NATIVE_POSITION_MODES and m not in _proxy.POSITION_MODES]


def recorded_served_positions_of_cell(doc: object, cell: str) -> Optional[List[str]]:
    """``doc[served_positions][cell]`` — the ENGINE-NEUTRAL map
    (:data:`SERVED_POSITIONS_KEY`, native-positions-resolve: the lens legs'
    stated modes and every lora route's attested mode, one shape) — as a list
    of modes, ``None`` when the document, the map (an older record) or the cell
    is absent. The served driver reads it FIRST and falls back to
    :func:`served_positions_of_cell` (the lens map) on an older record."""
    if not isinstance(doc, Mapping):
        return None
    table = doc.get(SERVED_POSITIONS_KEY)
    if not isinstance(table, Mapping) or cell not in table:
        return None
    return _served_modes(table[cell])


def _served_modes(modes: object) -> Optional[List[str]]:
    """A served-positions value as a list of mode strings — one mode, or a
    list / tuple of them; ``None`` for any other shape."""
    if isinstance(modes, str):
        return [modes]
    if isinstance(modes, (list, tuple)):
        return [str(m) for m in modes]
    return None


# --------------------------------------------------------------------------- #
# WHICH FAMILIES MAY BE SERVED THINKING-ON (the launcher refuses                #
# at plan time, never silently OFF)                                            #
# --------------------------------------------------------------------------- #
#
# Measured from the local tokenizer cache, offline, by rendering each family's
# chat with add_generation_prompt True/False under enable_thinking False/True —
# the difference IS `response_header_len`, the span a fitted object's response
# mask keys on (`configs/tinycap/thinking_header_verification.md`; five rows measured
# 2026-09-04, GLM-4.6V and Nemotron-3-Nano measured 2026-09-09 by the same
# method with the five re-measured byte-for-byte; raw output in
# `thinking_header_measure_2026-09-09.json` beside it). What it found, and what
# each fact licenses:
#
#   gemma-4 (E4B and E2B): template DOES carry `enable_thinking`, but the
#     assistant header is IDENTICAL in both modes — `<|turn>model\n`, H=3.
#     Gemma signals thinking with a LEADING system turn, at the FRONT of the
#     prompt, so the mask boundary is invariant and a fitted gemma cell may
#     serve thinking-ON. (The thinking-ON fitted runs already taken at 1983322
#     are therefore NOT mask-misaligned.)
#   Qwen3.5 (9B and 4B): H moves 7 -> 5. OFF closes the block inside the header
#     (`<|im_start|>assistant\n<think>\n\n</think>\n\n`), ON leaves it open
#     (`…<think>\n`). An object fit at H=7 served at H=5 masks two tokens of the
#     model's own thinking as if they were the response — a DIFFERENT
#     intervention than was fit, producing plausible-looking numbers.
#   Llama-3: no switch in the template at all — thinking-OFF by property, not
#     by exception.
#   GLM-4.6V-Flash @411bb4d7 (measured 2026-09-09): H moves 5 -> 2, in the
#     OPPOSITE shape from Qwen. OFF prefills the closed empty block inside the
#     header (`<|assistant|>\n<think></think>\n`, ids [151337, 198, 151350,
#     151351, 198]); ON appends only `<|assistant|>\n` ([151337, 198]) — a
#     strict PREFIX of the OFF header with NO think tag in the prompt: the
#     completion emits both `<think>` and `</think>` itself (explicit tags).
#     OFF also appends the control token `/nothink` (151360) to every user
#     turn. The id-level derivation certifies both arms
#     (`chat_markers.thinking_header_facts` -> moves: True).
#   Nemotron-3-Nano-4B @dfaf35de (measured 2026-09-09): the case a WIDTH
#     comparison cannot see. H is 6 in BOTH modes — OFF [10, 1503, 19464,
#     1010, 12, 13] (`<|im_start|>assistant\n<think></think>`), ON [10, 1503,
#     19464, 1010, 12, 1010] (`...<think>\n`) — same width, different LAST
#     token, and ON leaves the think block OPEN (Qwen's implicit-open shape at
#     an unchanged width). Mask-moving in SUBSTANCE: the masked region changes
#     character (reasoning + `</think>` + answer instead of the answer), so it
#     must NOT join HEADER_INVARIANT_THINKING_FAMILIES. Its ON header is
#     REFUSED by `chat_markers._appended_generation_header`'s prefix rule today
#     (the generation prompt's `<think>\n` is not a text prefix of the
#     completed turn's `<think></think>`): `thinking_header_facts_or_error`
#     records on_ids None / moves None, and a declared-ON nemotron_h lens cell
#     has no attested ON header and fails CLOSED (proxy
#     `thinking_on_unattested`). A width-only reading would have admitted it
#     silently — that is the hazard, not a licence.
#
# Note the mask question is separate from the PARSER question below: a family
# may have an invariant header and still lack a verified reasoning parser, in
# which case thinking-ON is refused for a different reason (thought text lands
# in `content`, where every extractor reads it as the answer).

#: family -> why a FITTED cell of it cannot be served thinking-ON (the served
#: render is pinned OFF by ``vllm_server.THINKING_OFF_TEMPLATE_KWARGS`` and the
#: header MOVES between modes, so the object's fit-time mask does not survive).
MASK_MOVING_THINKING_FAMILIES: Mapping[str, str] = {
    "qwen3_5": ("its assistant header MOVES between modes — measured H=7 thinking-OFF "
                "(the empty <think></think> closed inside the header) vs H=5 thinking-ON "
                "(left open), so an object fit at 7 and served at 5 masks two tokens of the "
                "model's own thinking as if they were the response"),
    "glm4v": ("its assistant header MOVES between modes — measured 2026-09-09: H=5 "
              "thinking-OFF (<|assistant|>\\n<think></think>\\n, ids [151337, 198, 151350, "
              "151351, 198]) vs H=2 thinking-ON (<|assistant|>\\n, ids [151337, 198]); the ON "
              "header is a strict PREFIX of the OFF header and carries NO think tag (the "
              "completion emits <think> and </think> itself), so an object fit at 5 and "
              "served at 2 steers three fewer prompt positions and the whole model-emitted "
              "think block as if it were the response"),
    "nemotron_h": ("its assistant header MOVES between modes by ID, NOT by width — measured "
                   "2026-09-09: H=6 thinking-OFF (ids [10, 1503, 19464, 1010, 12, 13], "
                   "<|im_start|>assistant\\n<think></think>) vs H=6 thinking-ON (ids [10, 1503, "
                   "19464, 1010, 12, 1010], <|im_start|>assistant\\n<think>\\n): same width, "
                   "different last token, and ON leaves the think block OPEN so the model's own "
                   "reasoning lands inside the response mask; a width comparison reads it as "
                   "invariant and would admit it SILENTLY. Its thinking-ON header is REFUSED by "
                   "the id-level derivation today (chat_markers prefix rule: the generation "
                   "prompt's <think>\\n is not a prefix of the completed turn's <think></think>), "
                   "so a declared-ON nemotron_h lens cell has NO attested ON header and fails "
                   "closed (proxy thinking_on_unattested) — NOT admissible on width alone"),
}
#: Families whose chat template carries NO thinking switch at all — thinking-ON
#: is not expressible, for a prompted or a fitted cell alike.
NO_THINKING_CHANNEL_FAMILIES: Tuple[str, ...] = ("llama",)
#: Families MEASURED to keep the same assistant header in both modes, i.e. the
#: ones whose FITTED cells may serve thinking-ON.
HEADER_INVARIANT_THINKING_FAMILIES: Tuple[str, ...] = ("gemma4",)
#: Where the measurement lives (quoted in the refusals, so an operator can read
#: the evidence rather than take the refusal on faith).
THINKING_HEADER_EVIDENCE = ("configs/tinycap/thinking_header_verification.md (measured 2026-09-09; "
                            "the 2026-09-04 rows reproduce byte-for-byte; raw ids in "
                            f"{THINKING_HEADER_MEASURE_JSON})")


def thinking_on_refusal(family: str, *, fitted: bool, header_located: bool = True,
                        certified_split_ok: bool = False,
                        require_certified: bool = True) -> Optional[str]:
    """Why this family cannot be served thinking-ON — or ``None`` when it can.

    Two independent reasons, checked in the order that gives the most specific
    message. (b) A FITTED cell whose served mask is HEADER-LOCATED
    (``header_located``: some served op's positions are in
    :data:`HEADER_LOCATED_MODES`) on a family whose header moves: the object
    would be applied to a different span than it was fit at. A fitted cell
    with NO header-located op (a ``positions: all`` object) is mask-invariant
    under either render and is NOT refused here — its admission is the OOS
    tuple's (the fitted intervention served under a render its fit never
    saw). (a) Any cell of a family with no VERIFIED parser: no server reasoning
    parser (:data:`REASONING_PARSER_BY_FAMILY`) — and, when the caller OPTS IN
    with ``certified_split_ok`` (the math500-thinking-on-full22 driver and dry
    run), no CERTIFIED harness-side split mode either
    (:data:`FAMILY_RENDER_FACTS`) — the thought text would be read as the
    answer. A ``candidate`` fact refuses under ``require_certified``
    (production; the dry run's `pre` stage passes False). Never a silent OFF,
    for either. ``header_located`` and ``certified_split_ok`` default to the
    pre-existing answer, so every existing caller — the Modal launcher's plan,
    which derives the parent 2x2's out-of-support posture from THIS refusal —
    is byte-identical: flipping the default would have moved the parent's base
    leg from its authorised 8192 to the ON floor and parted the two doors."""
    if fitted and header_located and family in MASK_MOVING_THINKING_FAMILIES:
        return (f"family {family!r} serves its fitted objects under a render pinned thinking-OFF "
                f"(vllm_server.THINKING_OFF_TEMPLATE_KWARGS, keyed on the same "
                f"'enable_thinking' in the template that the FIT side keys on) and "
                f"{MASK_MOVING_THINKING_FAMILIES[family]} — a re-fit under thinking-ON would be a "
                f"new object, not a re-run. Evidence: {THINKING_HEADER_EVIDENCE}")
    if family not in REASONING_PARSER_BY_FAMILY:
        if family in NO_THINKING_CHANNEL_FAMILIES:
            why = ("its chat template carries no thinking switch at all — thinking-ON is not "
                   "expressible")
        elif certified_split_ok:
            fact_why = render_fact_refusal(family, require_certified=require_certified)
            if fact_why is None:
                return None          # the certified harness-side split IS the family's parser
            why = f"no reasoning parser has been VERIFIED for it and {fact_why}"
        else:
            why = "no reasoning parser has been VERIFIED for it"
        return (f"family {family!r} has no pinned reasoning parser "
                f"(REASONING_PARSER_BY_FAMILY: {sorted(REASONING_PARSER_BY_FAMILY)}): {why}. "
                "Serving thinking-ON anyway would leave the thought text in 'content', where "
                "every extractor reads it as the answer")
    return None


def fitted_thinking_on_out_of_support(family: object, *, header_located: bool) -> Optional[str]:
    """WHY a FITTED cell (a lens route) served under the thinking-ON render is
    outside its fit support — or ``None`` when that serve IS in support. A fact
    about the ROUTE and the RENDER alone: never about
    :data:`FLAG_ALLOW_OOS_THINKING`, which is the operator's ACKNOWLEDGEMENT of
    this fact, not its trigger. Two ways out of support, checked in the order
    that gives the most specific reason:

    * the served mask is NOT header-located (a ``positions: all`` / ``last``
      object): mask-invariant under either render, but the fitted intervention
      meets a chat render its fit never saw — the ``document_fit`` served
      thinking-ON (the gemma exception was withdrawn, so this holds
      for EVERY family).
    * the served mask IS header-located on a family whose header MOVES between
      the arms (:data:`MASK_MOVING_THINKING_FAMILIES`): the object would be
      applied to a different span than it was fit at (the parent
      experiment's declared ``@thinking`` path).

    In support: a header-located object on a header-INVARIANT family (the
    campaign's gemma psr cells, fit on the chat template and served at the same
    header under both arms). A run for which this returns a reason MUST carry
    the override, a matching registry tuple and the artifact digest, and runs
    the predicates (A) + (B) or (B′)/(C) — the driver refuses by name otherwise,
    flag or no flag; a non-lens route (bare, prompted) is never asked."""
    if not header_located:
        return ("the object's served mask is not header-located (positions all/last): the fitted "
                "intervention is served under the thinking-ON render its fit never saw (plan §4.5; "
                "D12 P1-5 — every family, gemma included)")
    fam = str(family) if family is not None else None
    if fam in MASK_MOVING_THINKING_FAMILIES:
        return (f"the object's served mask is header-located and family {fam!r} moves its assistant header "
                f"between the arms ({MASK_MOVING_THINKING_FAMILIES[fam]}) — the object would be applied to "
                "a different span than it was fit at (plan §4.3 item 1b)")
    return None


# --------------------------------------------------------------------------- #
# §PW-oos (U10 item 5) — the explicit out-of-support-thinking override         #
# --------------------------------------------------------------------------- #

#: What ``--allow-out-of-support-thinking`` means, quoted verbatim into every
#: record that says a refusal was overridden, so a reader of a store, a REC or
#: an evidence.json never has to reconstruct it.
OUT_OF_SUPPORT_THINKING_NOTE = (
    "--allow-out-of-support-thinking: an EXPLICIT, named override for ONE authorised "
    "experiment (U10 item 5) — it serves a thinking-ON request on a family whose fitted "
    "objects were derived under the pinned thinking-OFF render, which is serving OUTSIDE "
    "the fit support. It LIFTS: the plan-time per-family thinking refusal "
    "(thinking_on_refusal), the no-verified-parser standup composition (a thinking-ON "
    "standup then serves NO reasoning parser, so thought text stays in 'content'), and the "
    "mixed-arm header-invariance REFUSAL. It KEEPS: the header MEASUREMENT (both arms, "
    "through the live /v1/tokenize, written to evidence.json), every other positive control, "
    "and the object-identity check. It stamps out_of_support_thinking=true into the hashed "
    "store identity, so an out-of-support store can never resume into or merge with an "
    "in-support one. It changes NOTHING when it is absent.")
#: What ``--allow-off-cap-override`` means, quoted
#: verbatim into the dry run and every REC of a comparator configuration — the
#: twin of :data:`OUT_OF_SUPPORT_THINKING_NOTE` for the SECOND named override.
OFF_CAP_OVERRIDE_NOTE = (
    "--allow-off-cap-override: an EXPLICIT, named override for ONE authorised comparator "
    "(contracts.AUTHORISED_OFF_CAP_COMPARATOR) — experiment 1's thinking-OFF legs re-run at the "
    "thinking-ON completion cap, so cap relief (OFF/8192 - OFF/512) and the render effect at a "
    "matched budget (ON/8192 - OFF/8192) can each be read on its own. It LIFTS: nothing — no "
    "refusal is lifted, the render is the fit render (thinking-OFF, in support). It CHANGES: "
    "exactly two things — the EXECUTED thinking-OFF cap of the tasks the comparator names "
    "(the table's 512 -> 8192 on the GSM8K tasks) and the presence of the hashed identity key "
    "max_tokens_by_task (the ONE optional key such a store carries), so a comparator store can "
    "never resume into or merge with a table-cap store. It KEEPS: declaration-free requests on "
    "every route (no declaration is sent; the base route's refusal of the key is probed live), "
    "the strict conditional stamp policy on the psr leg, render_regime thinking_off, "
    "think_split_mode record_only, the bare cell spellings on the standup, every positive "
    "control, and it holds the containers to the LANDED record with the fail-closed presence "
    "rules (the declarations map and null error key, the object digest, the salt policy, the "
    "prompt-budget artifact). It is mutually exclusive with the out-of-support thinking override "
    "(the first named override; the two flags are never named together). It changes NOTHING when "
    "it is absent.")
#: The one refusal the override may NOT lift: a family whose chat template
#: carries no thinking switch at all has no thinking-ON render to serve, so
#: ``enable_thinking`` is inert and there is nothing to override — naming the
#: flag there would produce a silently thinking-OFF run labelled ON.
OUT_OF_SUPPORT_THINKING_NOT_OVERRIDABLE = (
    "and --allow-out-of-support-thinking cannot override it: this family's chat template "
    "carries no thinking switch, so there is no thinking-ON render to serve out of support "
    "— the flag would produce a thinking-OFF run recorded as ON")


def out_of_support_thinking_overridable(family: str) -> bool:
    """Whether :data:`FLAG_ALLOW_OOS_THINKING` may lift this family's
    thinking-ON refusal. True for the two OUT-OF-SUPPORT reasons (a header
    that MOVES between arms, no VERIFIED reasoning parser) — both are about
    serving outside the regime an object was fit in, which is exactly what the
    experiment measures. False for :data:`NO_THINKING_CHANNEL_FAMILIES`
    (:data:`OUT_OF_SUPPORT_THINKING_NOT_OVERRIDABLE`)."""
    return family not in NO_THINKING_CHANNEL_FAMILIES


def thinking_on_override_refusals(family: str, *, fitted: bool,
                                  header_located: bool = True) -> Tuple[str, ...]:
    """EVERY thinking-ON refusal :data:`FLAG_ALLOW_OOS_THINKING` lifts for this
    family, most specific first — the reasons a record must carry so an
    overridden refusal is stated rather than vanished.

    :func:`thinking_on_refusal` returns only the most specific one, because a
    refusal needs one message; an override record needs them ALL, since on
    qwen3_5 BOTH bind (the fit-regime header move AND the missing parser) and
    a record naming one would understate what was overridden. ``header_located``
    is the cell's served-mask predicate; an all-position
    fitted cell lists no mask-moving refusal (there is none to lift)."""
    out: List[str] = []
    if fitted and header_located and family in MASK_MOVING_THINKING_FAMILIES:
        out.append(thinking_on_refusal(family, fitted=True, header_located=True) or "")
    parser = thinking_on_refusal(family, fitted=False)
    if parser:
        out.append(parser)
    return tuple(r for r in out if r)

# --------------------------------------------------------------------------- #
# proxy facts (E1/E3/E4/E6) — re-exported from proxy.py, never retyped         #
# --------------------------------------------------------------------------- #

#: The grader / unsteered base route is the routing table's entry for THIS
#: cell id; its virtual-model name is read from the table (P20).
ROUTE_NONE_CELL = "none"
#: The path-matched scale-0 twin of a lens route: ``<cell>__lens0`` /
#: ``none__lens0`` (the served driver's positive-control convention).
SCALE0_TWIN_SUFFIX = "__lens0"

#: THE PROXY'S PETRI-FACING AGENT-LOOP ENTRY AS A SERVED FACT (U4(b) / PW18).
#: ``RoutingProxy.petri_agent_loop_entry`` (``--petri-agent-loop`` on the
#: standup, ON by default) declares ``petri_agent_loop`` for every lens-route
#: request whose structure is a turn of the agent loop and whose render does
#: not end at the generation header, so the worker locates the response
#: boundary at the LAST header and steers header + tool call + tool response
#: + generated (the completed gemma-E4B Petri audit's regime). It changes
#: WHICH positions are steered on a tool turn, so it is served identity.
#: Three spellings of one fact, pinned equal by test: the proxy's ``/v1/models``
#: identity block (``petri_proxy.petri_agent_loop_entry`` — the AUTHORITATIVE
#: live source, read the way ``petri_runner.require_agent_loop_entry`` reads
#: it), the standup's ``endpoint.json`` record (``agent_loop_entry``, what
#: ``capctrl_serving_up.py`` launched), and the cell manifest's ``route`` block
#: + ``resolved_config.tinycap.served`` (``agent_loop_entry`` —
#: :data:`AGENT_LOOP_ENTRY_KEY`, defined with the manifest keys above).
PROXY_IDENTITY_KEY = "petri_proxy"
PROXY_IDENTITY_AGENT_LOOP_ENTRY = "petri_agent_loop_entry"
#: The standup CLI's stated opt-out (the ONLY way the entry is off).
FLAG_NO_PETRI_AGENT_LOOP = "--no-petri-agent-loop"

#: THE LENS HOOK'S REDUCTION MODE AS A SERVED FACT (E25 / PW18; E29 / PW18b).
#: The stacked-reductions landing changes every fitted cell's served
#: arithmetic from per-row-inside-group (bit-identical to legacy) to one
#: stacked GEMM per group — ulp-level logit differences on EVERY decode step
#: (same class of nondeterminism as batch composition, PW5-4, but present at
#: every step), so pre- and post-landing stores are not comparable at the
#: token / logprob level and must never resume into each other. THE SERVED
#: ATTESTATION IS THE SOURCE OF TRUTH (E29): the mode is read from the
#: standup's ``endpoint.json`` / the proxy identity block under
#: :data:`PROXY_IDENTITY_REDUCTION_MODE` (every post-landing server emits it);
#: only a server that itself reports NO such key — a pre-landing server — is
#: :data:`REDUCTION_MODE_PER_ROW`, never null, so every existing store maps to
#: ``per_row``. ``SISTEER_LENS_STACKED_REDUCTIONS`` (:data:`LENS_STACKED_REDUCTIONS_ENV`)
#: is the STANDUP's switch, and the parser's rule is: UNSET or empty ->
#: STACKED; ``0`` / ``per_row`` / ``off`` -> per_row; ``1`` / ``stacked`` ->
#: stacked; anything else refuses. THE UNSET BRANCH FLIPPED TO STACKED WITH
#: THE LANDING (E46, 2026-09-06): the stacked-reductions change is on
#: ``origin/main`` at f39a4562 and merged into this branch, so a worker spawned
#: from this tree with the switch unset serves STACKED —
#: ``lens_adapters.parse_reduction_mode`` is the serving parser and its unset
#: branch is ``stacked``. The earlier opposite reading (E31: unset = per_row)
#: was correct against every tree that existed THEN, when the landing had not
#: happened and no server attested ``lens_reduction_mode``; it is wrong against
#: this one. Exactly ONE branch of this parser moved (E31 said it would) — the
#: launcher passes an explicit value, so nothing it launches rides on the
#: default, and :data:`REDUCTION_MODE_LAUNCHER_DEFAULT` deliberately did NOT
#: move (per_row: the wave in flight runs per_row on its own frozen
#: pre-landing tree). Nor did :data:`REDUCTION_MODE_DEFAULT`, which answers a
#: different question — what a SERVER that reports no key served, i.e. a
#: pre-landing server, which is per_row forever. One vocabulary difference
#: from the serving parser remains, in the safe direction: that parser also
#: accepts ``true`` / ``on`` / ``yes`` / ``all`` / ``false`` / ``no``,
#: case-insensitively and whitespace-tolerantly, where this one refuses them.
#: A spelling only this parser refuses is a loud refusal before any GPU
#: minute, never a wrong expectation.
#: :func:`reduction_mode_from_env` is THAT parser, exactly, so a
#: launcher / driver derives the same EXPECTATION the server derives from one
#: environment — and it is only ever an expectation:
#: :func:`check_reduction_mode_expectation` REFUSES loudly when it and the
#: attested value disagree (a keyless, pre-landing server equals per_row only
#: when per_row was expected; an expectation of stacked against a keyless
#: server refuses) — a disagreement is never recorded into identity. The
#: launcher does not rely on two implicit defaults: it passes ONE canonical
#: value into the standup environment (``--reduction-mode``, default per_row
#: until a stacked sha is adopted). The identity field is
#: :data:`REDUCTION_MODE_FIELD` (defined with the manifest keys above).
PROXY_IDENTITY_REDUCTION_MODE = "lens_reduction_mode"
REDUCTION_MODE_PER_ROW = "per_row"
REDUCTION_MODE_STACKED = "stacked"
REDUCTION_MODES: Tuple[str, ...] = (REDUCTION_MODE_PER_ROW, REDUCTION_MODE_STACKED)
#: What a server that reports NO reduction-mode key served: a pre-landing
#: server, per-row (E25 / E29). Never applied over a stated value.
REDUCTION_MODE_DEFAULT = REDUCTION_MODE_PER_ROW
#: ``route.reduction_mode_error`` — the reason a store HAS the field and could
#: not say what it served. Quoted in the refusal when a store states one.
STORE_REDUCTION_MODE_ERROR_FIELD = "reduction_mode_error"
#: :attr:`StoreReductionMode.provenance`: the store NAMED the mode, or a store
#: whose tree does not contain the stamp was silent and its silence MEANS per_row
#: (E54 #2). Same arithmetic, different facts — only one is the store speaking.
REDUCTION_MODE_STATED = "stated"
REDUCTION_MODE_LEGACY = "legacy"

#: THE SERVING ENGINE AS SERVED IDENTITY (since 2026-09-13 the plugin-free
#: native multi-LoRA engine is the production default for every LoRA cell).
#: Two engines serve a cell: the LENS
#: (a vLLM plugin hook with a reduction mode, a salt policy, serve declarations)
#: and the NATIVE multi-LoRA engine (a PEFT adapter at every position, CUDA
#: graphs on, none of the lens facts). A passthrough leg (``none``, a prompted
#: cell) carries the SAME serving identity (``proxy_vllm+passthrough+…``) on
#: both, so the identity alone cannot keep a lens-era ``none`` store apart from
#: a native-era one — hence ``serving_engine``: PRESENT IFF NATIVE in the hashed
#: ``served`` block (:func:`served_identity_fields` with ``native=True``; the
#: lens key set is byte-identical), recorded UNHASHED on every row and route
#: block of both engines by the writers, and read back by every consumer
#: through the ONE resolver (:func:`read_store_reduction_mode`) so a store is
#: single-engine and a cross-engine resume or pairing refuses by name.
#: ``NOT_APPLICABLE`` is the explicit value a native record carries where a
#: lens fact would go — the reduction mode first of all
#: (:data:`REDUCTION_MODE_NOT_APPLICABLE`), so the launcher's resume guard
#: (``route.get(REDUCTION_MODE_FIELD, REDUCTION_MODE_DEFAULT)``) never falls to
#: ``per_row`` on a native store. Deliberately NOT a member of
#: :data:`REDUCTION_MODES`: :func:`resolve_reduction_mode` and
#: :func:`check_reduction_mode_expectation` are lens readers and are not
#: consulted on a native endpoint (recorded ``reduction_mode_expectation:
#: not_consulted`` by the driver). The row-facing spelling is
#: ``serving_engine`` everywhere (``engine`` already means three things:
#: ``row_constants.engine == "vllm"``, ``endpoint.json.engine ==
#: "lora_native"``, a Petri row's ``engine`` = its serving identity).
NOT_APPLICABLE = "not_applicable"
REDUCTION_MODE_NOT_APPLICABLE = NOT_APPLICABLE
SERVED_ENGINE_FIELD = "serving_engine"
SERVING_ENGINE_LENS = "lens"
#: the native engine's name — ``serving_attestation.SERVING_ATTESTATION_KIND`` /
#: ``proxy.ENGINE_KIND_LORA_NATIVE`` / ``lora_serving_up.ENGINE``, by reference
#: to the proxy vocabulary this module already imports
SERVING_ENGINE_LORA_NATIVE = _proxy.ENGINE_KIND_LORA_NATIVE
SERVING_ENGINES: Tuple[str, ...] = (SERVING_ENGINE_LENS, SERVING_ENGINE_LORA_NATIVE)
#: ``endpoint.json.engine`` — the native core's own spelling of what it serves
#: (``lora_serving_up.ENGINE``; a lens standup's record has no such key); the
#: core also writes the row-facing ``serving_engine`` beside it
ENDPOINT_KEY_ENGINE = _proxy.ENGINE_KEY
#: the reason key a lens standup writes beside a null ``lens_reduction_mode``
#: (``lens_worker.LENS_REDUCTION_MODE_ERROR_KEY``; a literal here so this
#: torch-free module gains no import — pinned equal by test)
LENS_REDUCTION_MODE_ERROR_KEY = "lens_reduction_mode_error"


def endpoint_is_native(ep: object) -> bool:
    """Whether a standup ``endpoint.json`` record (capctrl's, mt's or the native
    core's shape) is the NATIVE multi-LoRA engine's: its :data:`ENDPOINT_KEY_ENGINE`
    (``engine``) — or, absent that, the row-facing :data:`SERVED_ENGINE_FIELD` the
    core writes beside it — equals :data:`SERVING_ENGINE_LORA_NATIVE`. A lens
    record carries neither key (False); a non-mapping is False (the callers
    refuse that shape in their own words). The ``/v1/models`` identity block's
    ``engine`` is a MAPPING (``{"kind": …}``): its ``kind`` is read, so the same
    predicate answers over either document. A record carrying BOTH spellings
    that disagree is torn and refuses (``ValueError``) rather than reading
    either."""
    if not isinstance(ep, Mapping):
        return False
    engine = ep.get(ENDPOINT_KEY_ENGINE)
    if isinstance(engine, Mapping):
        engine = engine.get("kind")
    row = ep.get(SERVED_ENGINE_FIELD)
    if engine is not None and row is not None and engine != row:
        raise ValueError(
            f"the standup record states {ENDPOINT_KEY_ENGINE}={engine!r} and {SERVED_ENGINE_FIELD}="
            f"{row!r} — two spellings of one engine that disagree; a torn record, refusing to read either")
    return (engine if engine is not None else row) == SERVING_ENGINE_LORA_NATIVE


def served_reduction_mode(ep: object, *, source: str = "standup endpoint record") -> str:
    """The ``reduction_mode`` a served store records as identity, read off a
    WHOLE standup endpoint record — engine-aware:

    * a NATIVE record (:func:`endpoint_is_native`) -> :data:`REDUCTION_MODE_NOT_APPLICABLE`;
      a native record that ALSO states a ``lens_reduction_mode`` is torn (a
      native engine has no lens hook to attest a mode for) and refuses;
    * a LENS record -> the three readings of ``lens_worker.endpoint_reduction_mode``
      (E61), exactly, torch-free: a NAMED mode (a member of :data:`REDUCTION_MODES`)
      is that mode; NEITHER ``lens_reduction_mode`` nor
      :data:`LENS_REDUCTION_MODE_ERROR_KEY` stated is a PRE-LANDING standup,
      ``per_row`` (a null mode with NO reason reads the same); a null mode WITH
      a stated reason refuses, quoting it — never the default recorded as the
      identity of a server whose arithmetic nobody could establish;
    * a record naming an ENGINE outside :data:`SERVING_ENGINES` (``engine`` is
      read as :func:`endpoint_is_native` reads it: the bare kind or the identity
      block's ``{"kind": ...}``, else the row-facing ``serving_engine``) refuses
      — an unknown engine has no reduction mode anyone can read; ``"lens"`` is
      accepted as the lens readings (the two Modal copies do the same).

    Every refusal is a ``ValueError`` naming ``source`` (a torn record —
    ``engine`` and ``serving_engine`` disagreeing — is :func:`endpoint_is_native`'s
    own ``ValueError``). Pinned case by case against
    ``lens_worker.endpoint_reduction_mode`` by test (the two must never
    disagree about one record)."""
    if not isinstance(ep, Mapping):
        raise ValueError(f"{source}: not a mapping ({type(ep).__name__}) — no reduction mode can be read from it")
    stated = ep.get(PROXY_IDENTITY_REDUCTION_MODE)
    if endpoint_is_native(ep):
        if stated is not None:
            raise ValueError(
                f"{source}: a native multi-LoRA standup ({ENDPOINT_KEY_ENGINE}={SERVING_ENGINE_LORA_NATIVE!r}) "
                f"states {PROXY_IDENTITY_REDUCTION_MODE}={stated!r} — it has no lens hook to attest a "
                "reduction mode for; a torn record, refusing rather than reading either fact")
        return REDUCTION_MODE_NOT_APPLICABLE
    engine = ep.get(ENDPOINT_KEY_ENGINE)
    if isinstance(engine, Mapping):
        engine = engine.get("kind")
    if engine is None:
        engine = ep.get(SERVED_ENGINE_FIELD)
    if engine is not None and engine != SERVING_ENGINE_LENS:
        raise ValueError(
            f"{source}: {ENDPOINT_KEY_ENGINE}={engine!r} is neither {SERVING_ENGINE_LENS!r} nor "
            f"{SERVING_ENGINE_LORA_NATIVE!r} — no reduction mode can be read for an unknown engine")
    why_none = ep.get(LENS_REDUCTION_MODE_ERROR_KEY)
    if stated is None:
        if why_none:
            raise ValueError(
                f"{source}: {PROXY_IDENTITY_REDUCTION_MODE} is null and {LENS_REDUCTION_MODE_ERROR_KEY} is "
                f"{why_none!r} — the standup could not determine the lens reduction mode its own workers "
                f"served, so this is not a pre-landing server (which states neither key and means "
                f"{REDUCTION_MODE_PER_ROW!r}); refusing rather than recording the default as served identity")
        return REDUCTION_MODE_PER_ROW
    if stated not in REDUCTION_MODES:
        raise ValueError(
            f"{source}: {PROXY_IDENTITY_REDUCTION_MODE}={stated!r} is not one of {list(REDUCTION_MODES)}")
    return str(stated)


class StoreReductionMode(NamedTuple):
    """What a store's manifest says about the lens arithmetic it was served
    under. ``why`` always says which reading held, so a caller's message names
    the store rather than the rule. ``serving_engine`` (defaulted, so every
    existing construction is unchanged) is the engine the route block STATES —
    :data:`SERVING_ENGINE_LORA_NATIVE` on a native store, ``"lens"`` when a
    lens store states it, ``None`` when the block carries no key (a lens store
    by era: every store written before the field existed)."""

    mode: Optional[str]
    refusal: Optional[str]
    why: str
    provenance: Optional[str] = None
    serving_engine: Optional[str] = None


def read_store_reduction_mode(manifest: Optional[Mapping[str, object]], *, where: str
                              ) -> StoreReductionMode:
    """E49 / E54 #2, made THE ONE resolver by E55 #3: what a served store's
    manifest says about its lens reduction mode. ``where`` names the manifest
    for the messages.

    Both readers of this fact call it — ``cell_controls.
    source_store_reduction_mode`` at the merge and ``pairing.
    store_reduction_mode`` at the HF-vs-served comparison — because two
    implementations of one question is how they came to disagree about one
    store, twice: at round 16 over "key absent" vs "key present, null", and
    again at E55 #3, where pairing mapped ANY present route block lacking the
    key to per_row while cell_controls refused for a current or unknown store.
    Damage `manifest.route.reduction_mode` on a current STACKED store and
    pairing would pool it with a genuine per_row one.

    FOUR readings:

    * a NAMED mode (``provenance`` :data:`REDUCTION_MODE_STATED`);
    * KNOWN LEGACY (``per_row``, ``provenance`` :data:`REDUCTION_MODE_LEGACY`)
      — a route block with NO ``reduction_mode`` key on a store that
      positively says its tree does not contain the stamp (:func:`store_era`
      for :data:`CONTRACT_REDUCTION_MODE`). Every store served before the stacked
      landing was served per-row, so this is knowledge, not a default;
    * NOTHING STATED (``mode`` and ``refusal`` both None) — no manifest, or no
      ``route`` block at all (not a served-lens store). Nothing to inherit and
      nothing to refuse: an entry whose store is gone is still a legitimate
      thing to read;
    * STATED AND UNUSABLE (``refusal`` set) — the key is PRESENT and null, or
      names something outside :data:`REDUCTION_MODES`; or the key is ABSENT on
      a store whose tree DOES contain the stamp (or that cannot say). This
      tree's manifest
      writer records the mode on EVERY store, so a route block without one on
      a current store is a torn or hand-edited manifest, and reading the legacy
      meaning into it would be the missing-key inference E54 removed.

    ENGINE-AWARE: the route block's :data:`SERVED_ENGINE_FIELD` is read
    BESIDE the mode and the two are held to each other —
    ``serving_engine == "lora_native"`` iff
    ``reduction_mode == "not_applicable"``. A native store reads
    ``(not_applicable, None, why, stated, "lora_native")``; a block WITHOUT
    ``serving_engine`` is a lens store and reads EXACTLY as above (the four
    readings, ``serving_engine`` None — no key absence is ever read as native);
    a block stating ``"lens"`` reads the four readings with ``serving_engine``
    ``"lens"``. STATED AND UNUSABLE (``refusal`` set): a native block with a
    lens mode (or no mode), ``not_applicable`` without the native engine, or
    an engine outside :data:`SERVING_ENGINES` — a comparison across engines
    measures the engine as well as the intervention, so none of these is read
    around."""
    if not isinstance(manifest, Mapping):
        return StoreReductionMode(None, None, f"{where} is not a readable manifest")
    route = manifest.get(MANIFEST_KEY_ROUTE)
    if not isinstance(route, Mapping):
        return StoreReductionMode(None, None, (
            f"{where} states no {MANIFEST_KEY_ROUTE!r} block — not a served-lens store "
            "(an HF reference store has no lens reduction mode)"))
    stated = f"{where} {MANIFEST_KEY_ROUTE}.{REDUCTION_MODE_FIELD}"
    engine_stated = f"{where} {MANIFEST_KEY_ROUTE}.{SERVED_ENGINE_FIELD}"
    engine: Optional[str] = None
    if SERVED_ENGINE_FIELD in route:
        engine = route[SERVED_ENGINE_FIELD]
        if engine not in SERVING_ENGINES:
            return StoreReductionMode(None, (
                f"{engine_stated} is {engine!r}, which is not one of {list(SERVING_ENGINES)} — refusing "
                "to read an unknown serving engine (or a present null) as this entry's engine"),
                engine_stated)
        if engine == SERVING_ENGINE_LORA_NATIVE:
            mode = route.get(REDUCTION_MODE_FIELD)
            if REDUCTION_MODE_FIELD not in route or mode != REDUCTION_MODE_NOT_APPLICABLE:
                return StoreReductionMode(None, (
                    f"{engine_stated} is {SERVING_ENGINE_LORA_NATIVE!r} but {stated} is "
                    + (f"{mode!r}" if REDUCTION_MODE_FIELD in route else "absent")
                    + f" — a native store records {REDUCTION_MODE_NOT_APPLICABLE!r} (it has no lens hook); a "
                    "native block carrying a lens mode is torn or mislabelled and is not read as either "
                    "engine's arithmetic"), engine_stated, serving_engine=engine)
            return StoreReductionMode(REDUCTION_MODE_NOT_APPLICABLE, None,
                                      f"{engine_stated} = {SERVING_ENGINE_LORA_NATIVE!r}; {stated} = "
                                      f"{REDUCTION_MODE_NOT_APPLICABLE!r}",
                                      REDUCTION_MODE_STATED, engine)
    if REDUCTION_MODE_FIELD in route and route[REDUCTION_MODE_FIELD] == REDUCTION_MODE_NOT_APPLICABLE:
        return StoreReductionMode(None, (
            f"{stated} is {REDUCTION_MODE_NOT_APPLICABLE!r} but {engine_stated} is "
            + (f"{engine!r}" if SERVED_ENGINE_FIELD in route else "absent")
            + f" — only a {SERVING_ENGINE_LORA_NATIVE!r} store records that value; a lens store "
            "(or one naming no engine) with it is torn or mislabelled"), stated, serving_engine=engine)
    if REDUCTION_MODE_FIELD not in route:
        era, why_era = store_era(manifest, contract=CONTRACT_REDUCTION_MODE)
        if era == STORE_ERA_HISTORICAL:
            return StoreReductionMode(
                REDUCTION_MODE_PER_ROW, None,
                (f"{where} {MANIFEST_KEY_ROUTE} block has no {REDUCTION_MODE_FIELD} key and "
                 f"{why_era}, so it is a PRE-LANDING store: every store served before the "
                 f"stacked landing was served {REDUCTION_MODE_PER_ROW}"),
                REDUCTION_MODE_LEGACY, engine)
        return StoreReductionMode(None, (
            f"{where} {MANIFEST_KEY_ROUTE} block has no {REDUCTION_MODE_FIELD} key, and nothing "
            f"on that store says its tree lacks the stamp: {why_era}. This tree's manifest writer "
            "records the mode on EVERY store, so a route block without one is a torn or "
            f"hand-edited manifest, not a legacy {REDUCTION_MODE_PER_ROW} store — and reading the "
            "legacy meaning into it would be the missing-key inference this refuses. Re-merge "
            "that store from a tree whose standup attests the mode it served, or, if this store "
            "really is one this campaign wrote from a tree without the stamp, name its tree in "
            "contracts.KNOWN_PRODUCER_TREES with the contracts it does not contain — "
            "E54 #2 / E55 #3"),
            stated, engine)
    mode = route[REDUCTION_MODE_FIELD]
    why_none = route.get(STORE_REDUCTION_MODE_ERROR_FIELD)
    if mode is None:
        return StoreReductionMode(None, (
            f"{stated} is null"
            + (f" and {STORE_REDUCTION_MODE_ERROR_FIELD} is {why_none!r}" if why_none else "")
            + " — the store HAS the field and could not say what arithmetic it was served "
            f"under, so this is not a pre-landing store (which has no key at all and means "
            f"{REDUCTION_MODE_PER_ROW!r}); refusing rather than reading the default into it"),
            stated, engine)
    if mode not in REDUCTION_MODES:
        return StoreReductionMode(None, (
            f"{stated} is {mode!r}, which is not one of {list(REDUCTION_MODES)} "
            "— refusing to read an unknown lens reduction mode, or the default, as "
            "this entry's arithmetic"), stated, serving_engine=engine)
    return StoreReductionMode(mode, None, stated, REDUCTION_MODE_STATED, engine)


def reduction_mode_mismatch(a: object, b: object) -> Optional[str]:
    """Why two stores may NOT be pooled — served under different LENS REDUCTION
    MODES (E46) or, since native-serving-default, on DIFFERENT SERVING ENGINES —
    or ``None`` when they agree or when either side states nothing. Each side is
    a :class:`StoreReductionMode` (its ``mode`` is read) or a bare mode (a member
    of :data:`REDUCTION_MODES`, :data:`REDUCTION_MODE_NOT_APPLICABLE`, or None).
    ``pairing.reduction_mode_mismatch`` and ``cell_controls.reduction_mode_store_
    conflict`` inherit the rule through this one function:

    * ``not_applicable`` (a native store) vs any lens mode -> refused: different
      serving engines; a comparison across engines measures the engine as well
      as the intervention (a passthrough ``none`` leg has the SAME serving
      identity on both, so this is the compare that keeps the eras apart);
    * native vs native (``not_applicable`` both) -> ``None``;
    * ``stacked`` vs ``per_row`` -> the E46 refusal, byte-for-byte pairing's."""
    ma = a.mode if isinstance(a, StoreReductionMode) else a
    mb = b.mode if isinstance(b, StoreReductionMode) else b
    if ma is None or mb is None or ma == mb:
        return None
    if REDUCTION_MODE_NOT_APPLICABLE in (ma, mb):
        native, lens = (ma, mb) if ma == REDUCTION_MODE_NOT_APPLICABLE else (mb, ma)
        return (f"{REDUCTION_MODE_FIELD} {ma!r} vs {mb!r} — different serving engines: "
                f"{native!r} is a {SERVING_ENGINE_LORA_NATIVE!r} store (a PEFT adapter at every "
                f"position, no lens hook) and {lens!r} a lens store; a comparison across engines "
                "measures the engine as well as the intervention and is not poolable — compare "
                "within one engine (native-serving-default plan §1.3)")
    return (f"lens reduction mode {ma!r} vs {mb!r} — a stacked store and a per_row store were "
            "served under different arithmetic (one stacked GEMM per group vs B single-row "
            "calls; not bit-identical at B > 1) and are not poolable; compare within one mode, "
            "or re-run one side under the other (E46)")


class StoreServingEngine(NamedTuple):
    """What a store's manifest says about the ENGINE that served it, read off
    EVERY spelling the producer writes and INDEPENDENTLY of the lens reduction
    mode. ``engine`` is the resolved engine —
    :data:`SERVING_ENGINE_LORA_NATIVE`, :data:`SERVING_ENGINE_LENS` (stated, or
    BY ERA on a served store that states none), or ``None`` for a manifest that
    is not a served store's at all (an HF reference, no manifest); ``stated``
    is the value the manifest carries (``None`` when no spelling is present —
    what a report shows, so a lens store's report stays byte-identical);
    ``why`` names the spelling(s) read or the era rule applied."""

    engine: Optional[str]
    stated: Optional[str]
    refusal: Optional[str]
    why: str


#: where ``served_capability_run`` spells the engine of a store it writes, PRESENT IFF native on
#: every one: the top-level unhashed stamp (every store, the legacy XSTest / OR-Bench / MMLU
#: controls included), the hashed identity's ``resolved_config.serving`` (every store), the
#: tinycap ``route`` block and the hashed ``tinycap.served`` block (a tinycap run — the ONLY two
#: :func:`read_store_reduction_mode` sees, which is why a native legacy-controls store read
#: "nothing stated" there and paired with its lens counterpart)
SERVING_ENGINE_SPELLINGS: Tuple[Tuple[str, ...], ...] = (
    (SERVED_ENGINE_FIELD,),
    (MANIFEST_KEY_ROUTE, SERVED_ENGINE_FIELD),
    ("resolved_config", "serving", SERVED_ENGINE_FIELD),
    (MANIFEST_KEY_TINYCAP, "served", SERVED_ENGINE_FIELD),
)
#: the served driver's own ``engine`` stamp (``row_constants.engine`` too): what makes a manifest
#: a SERVED store's — an HF reference (``cell_controls_run``) writes ``"hf"`` and no ``serving_path``
SERVED_STORE_ENGINE_STAMP = "vllm"
#: the serving PATHS (``manifest.SERVING_PATHS``' proxy_vllm vocabulary) a store on each engine is written
#: under — what a present serving identity / ``serving_path`` must name BESIDE that engine's stamp:
#: ``lens`` is the lens's own and ``lora`` the native engine's; ``passthrough`` (the base / prompted legs)
#: is served on BOTH, and a passthrough identity beside ``lora_native`` is a valid unsteered native leg
#: (the native driver stamps its ``none`` / prompted routes so)
SERVING_PATHS_OF_ENGINE: Mapping[str, Tuple[str, ...]] = {
    SERVING_ENGINE_LENS: ("lens", "passthrough"),
    SERVING_ENGINE_LORA_NATIVE: ("lora", "passthrough"),
}


def _serving_path_evidence(manifest: Mapping[str, object], *, where: str, stated: str
                           ) -> Tuple[Dict[str, str], Optional[StoreServingEngine]]:
    """The serving PATH a store's manifest names, read off every present serving-identity spelling
    (top-level, the ``route`` block, the hashed ``resolved_config.serving``) and its parsed top-level
    ``serving_path`` — ``({spelling: path}, None)``, or ``({}, refusal)`` when a spelling is malformed, the
    path unknown, or two spellings disagree (a torn or hand-edited manifest). ``stated`` phrases the
    record's engine-stamp state for the messages (``stating no serving_engine under any spelling`` on an
    unstamped record, or ``stamping serving_engine='lens'``). THE ONE reader of this evidence for
    :func:`read_store_serving_engine`'s two branches: the identity is validated whether or not the
    record stamps an engine."""
    from sisteer.capeval import manifest as _cm  # torch-free; lazy, like _steered_path_of
    known_paths = {path for paths in _cm.SERVING_PATHS.values() for path in paths}
    evidence: Dict[str, str] = {}
    resolved = manifest.get("resolved_config")
    for label, node in (("serving_identity", manifest),
                        (f"{MANIFEST_KEY_ROUTE}.serving_identity", manifest.get(MANIFEST_KEY_ROUTE)),
                        ("resolved_config.serving.serving_identity",
                         resolved.get("serving") if isinstance(resolved, Mapping) else None)):
        if isinstance(node, Mapping) and "serving_identity" in node:
            try:
                evidence[label] = _steered_path_of(node["serving_identity"])
            except Exception as e:  # manifest.parse_serving_identity refuses a malformed identity
                return {}, StoreServingEngine(None, None, (
                    f"{where} {label} {node['serving_identity']!r} is not a serving identity ({e}) on a served store "
                    f"{stated} — a torn or hand-edited manifest; not read as either engine"), f"{where} {label}")
    if "serving_path" in manifest:
        stated_path = manifest["serving_path"]
        if stated_path not in known_paths:
            return {}, StoreServingEngine(None, None, (
                f"{where} serving_path {stated_path!r} is not one of {sorted(known_paths)} on a served store "
                f"{stated} — a torn or hand-edited manifest; not read as either engine"), f"{where} serving_path")
        evidence["serving_path"] = str(stated_path)
    if len(set(evidence.values())) > 1:
        return {}, StoreServingEngine(None, None, (
            f"{where} spells its serving path two ways: {evidence!r} — a torn or hand-edited manifest {stated}; not read as "
            "either engine"), f"{where} {sorted(evidence)}")
    return evidence, None


def read_store_serving_engine(manifest: Optional[Mapping[str, object]], *, where: str) -> StoreServingEngine:
    """THE ONE reader of a store's serving ENGINE, beside
    :func:`read_store_reduction_mode` (the lens arithmetic): every spelling in
    :data:`SERVING_ENGINE_SPELLINGS` that is present must name a member of
    :data:`SERVING_ENGINES` and all present spellings must agree — a null, an
    unknown value or two spellings that disagree is STATED AND UNUSABLE
    (``refusal`` set; a torn or hand-edited manifest is never read as either
    engine), and the stamps must agree with the serving IDENTITY the record
    carries: every present identity spelling and the
    parsed ``serving_path`` must name one path a store on that engine is written
    under (:data:`SERVING_PATHS_OF_ENGINE`; ``passthrough`` on both) — agreeing
    ``lens`` stamps beside a ``+lora+`` identity, or ``lora_native`` beside
    ``+lens+``, are a partially relabelled record and refuse. With no spelling
    present the manifest is dated by what it IS: a
    SERVED store (the driver's ``engine: "vllm"`` stamp, a ``serving_path``, or a
    ``route`` block) states no engine only when it predates the field or was
    written by the lens path — the native writers stamp it everywhere — so it
    is a LENS store BY ERA only on POSITIVE evidence: a
    ``lens`` or ``passthrough`` serving identity / ``serving_path`` on the
    record, or a producer record that dates the store before the stamp; a
    ``lora`` identity without the stamp is a torn NATIVE record and an
    undatable identity-less one is unknown — both REFUSE. Anything else (an HF
    reference, ``engine: "hf"``, or a manifest naming none of these) is not a
    served store and states nothing (``engine`` None: nothing to refuse,
    nothing to inherit — the HF-vs-served comparison keeps pairing)."""
    if not isinstance(manifest, Mapping):
        return StoreServingEngine(None, None, None, f"{where} is not a readable manifest")
    found: Dict[str, object] = {}
    for path in SERVING_ENGINE_SPELLINGS:
        node: object = manifest
        for key in path[:-1]:
            node = node.get(key) if isinstance(node, Mapping) else None
        if isinstance(node, Mapping) and path[-1] in node:
            found[".".join(path)] = node[path[-1]]
    if found:
        bad = {k: v for k, v in found.items() if v not in SERVING_ENGINES}
        if bad:
            return StoreServingEngine(None, None, (
                f"{where} {sorted(bad)} = {[bad[k] for k in sorted(bad)]!r}, not one of {list(SERVING_ENGINES)} — refusing "
                "to read an unknown serving engine (or a present null) as this store's engine"), f"{where} {sorted(found)}")
        values = sorted({str(v) for v in found.values()})
        if len(values) > 1:
            return StoreServingEngine(None, None, (
                f"{where} spells its serving engine two ways: {found!r} — a torn or hand-edited manifest; a store is "
                "single-engine and is not read as either"), f"{where} {sorted(found)}")
        engine = values[0]
        # The stamps' consensus is NOT the whole record. A partially relabelled manifest can carry agreeing
        # `lens` stamps while its serving identities (top-level, the route block, the hashed
        # resolved_config.serving) and its parsed `serving_path` still say `+lora+` / `lora` — and the reverse.
        # Returning on the stamps alone skipped every identity check below, so `compare_sides` pooled such a record
        # with a lens peer (and its mirror image with a native one). The identity evidence is read exactly as on an
        # unstamped record (one path across every present spelling, a known path, a well-formed identity) and then
        # held to the stamp through SERVING_PATHS_OF_ENGINE: `lens` beside `lora`, or `lora_native` beside `lens`,
        # is a torn or relabelled record and is not read as either engine; a passthrough identity is valid on both.
        # A stamped record naming no identity or path anywhere reads as its stamps, as before.
        evidence, torn = _serving_path_evidence(manifest, where=where, stated=f"stamping {SERVED_ENGINE_FIELD}={engine!r}")
        if torn is not None:
            return torn
        distinct = sorted(set(evidence.values()))
        if distinct and distinct[0] not in SERVING_PATHS_OF_ENGINE[engine]:
            path = distinct[0]
            owner = next((eng for eng, paths in SERVING_PATHS_OF_ENGINE.items() if path in paths and eng != engine), None)
            owned = (f"the {owner!r} engine's path" if owner is not None
                     else "a path no served store is written under")
            return StoreServingEngine(None, None, (
                f"{where} {sorted(found)} stamp {SERVED_ENGINE_FIELD}={engine!r} but {sorted(evidence)} name the {path!r} path "
                f"— {owned}; a {engine!r} store is written under {list(SERVING_PATHS_OF_ENGINE[engine])} only, so this is a "
                "partially relabelled or hand-edited manifest whose stamps and serving identity disagree on the engine; "
                "not read as either"), f"{where} {sorted(found)} vs {sorted(evidence)}")
        return StoreServingEngine(engine, engine, None, f"{where} {sorted(found)} = {engine!r}")
    served = (manifest.get("engine") == SERVED_STORE_ENGINE_STAMP or "serving_path" in manifest
              or isinstance(manifest.get(MANIFEST_KEY_ROUTE), Mapping))
    if not served:
        return StoreServingEngine(None, None, None, (
            f"{where} is not a served store's manifest (no engine {SERVED_STORE_ENGINE_STAMP!r} stamp, no serving_path, no "
            f"{MANIFEST_KEY_ROUTE!r} block) — an HF reference states no serving engine"))
    # A SERVED store stating no engine under any spelling is a LENS store only on POSITIVE historical evidence.
    # An earlier contract read every such store as lens BY ERA, so a native record torn of its four stamps — one
    # whose route identity says `+lora+` — read as lens and slipped past the cross-engine pairing guard. The
    # evidence, in order: every PRESENT serving-identity spelling (top-level, the `route` block, the hashed
    # resolved_config.serving) and the top-level `serving_path` (the parsed path) must agree on ONE path; `lens` is
    # the lens's own; `passthrough` (the base / prompted legs, served on both engines) is the lens's too, because
    # the native writers stamp EVERY native route and the lens writers none; `lora` is a torn NATIVE record and
    # refuses. With no identity or path at all, the store's own record must date it BEFORE the engine field:
    # historical for the template-check contract (store_era — the serving-engine stamp landed after that contract,
    # so a store that positively predates it predates the stamp) is lens by era; a current or undatable record is
    # unknown and refuses — never read as either engine. With no identity or path at all, a route block stating a
    # LENS reduction mode (`stacked` / `per_row`, :data:`REDUCTION_MODES`) is positive lens evidence in its own
    # right: only a lens standup records one (a native store records `not_applicable`, and
    # :func:`read_store_reduction_mode` refuses that value without the native stamp) — read before the producer
    # record, named.
    evidence, torn = _serving_path_evidence(manifest, where=where,
                                            stated=f"stating no {SERVED_ENGINE_FIELD} under any spelling")
    if torn is not None:
        return torn
    distinct = sorted(set(evidence.values()))
    if distinct == ["lora"]:
        return StoreServingEngine(None, None, (
            f"{where} {sorted(evidence)} name the native path ('lora') but the store stamps no {SERVED_ENGINE_FIELD} under "
            f"any spelling ({[list(p) for p in SERVING_ENGINE_SPELLINGS]!r}) — the native writers stamp it everywhere, so "
            f"this is a torn native record, not a {SERVING_ENGINE_LENS!r} store by era; refusing to read an unknown serving "
            "engine as either"), f"{where} {sorted(evidence)}")
    if distinct in (["lens"], ["passthrough"]):
        return StoreServingEngine(SERVING_ENGINE_LENS, None, None, (
            f"{where} is a served store's manifest stating no {SERVED_ENGINE_FIELD} under any spelling, and "
            f"{sorted(evidence)} name the {distinct[0]!r} path — the native writers stamp every native route, so this is a "
            f"{SERVING_ENGINE_LENS!r} store by era"))
    if distinct:
        return StoreServingEngine(None, None, (
            f"{where} {sorted(evidence)} name the {distinct[0]!r} path, which no served store is written under, on a store "
            f"stating no {SERVED_ENGINE_FIELD} under any spelling — a torn or hand-edited manifest; not read as either engine"),
            f"{where} {sorted(evidence)}")
    # no identity or path anywhere: a route block stating a LENS reduction mode is positive evidence on its own
    route = manifest.get(MANIFEST_KEY_ROUTE)
    lens_mode = route.get(REDUCTION_MODE_FIELD) if isinstance(route, Mapping) else None
    if lens_mode in REDUCTION_MODES:
        return StoreServingEngine(SERVING_ENGINE_LENS, None, None, (
            f"{where} is a served store's manifest stating no {SERVED_ENGINE_FIELD} under any spelling and no serving "
            f"identity or path, and its {MANIFEST_KEY_ROUTE}.{REDUCTION_MODE_FIELD} is the lens arithmetic {lens_mode!r} — "
            f"only a lens standup records one, so this is a {SERVING_ENGINE_LENS!r} store by era"))
    era, why_era = store_era(manifest, contract=CONTRACT_TEMPLATE_CHECK)
    if era == STORE_ERA_HISTORICAL:
        return StoreServingEngine(SERVING_ENGINE_LENS, None, None, (
            f"{where} is a served store's manifest stating no {SERVED_ENGINE_FIELD} under any spelling and no serving "
            f"identity or path, and {why_era} — the {CONTRACT_TEMPLATE_CHECK} contract predates the serving-engine stamp, so "
            f"this is a {SERVING_ENGINE_LENS!r} store by era"))
    return StoreServingEngine(None, None, (
        f"{where} is a served store's manifest stating no {SERVED_ENGINE_FIELD} under any spelling, naming no serving "
        f"identity or serving_path, and its record does not date it before the stamp ({why_era}) — an unknown serving "
        "engine; a torn native record and a keyless lens one are byte-identical here, so it is not read as either "
        "(name the identity the store was served under, or its producer tree / contract_version)"), f"{where} {SERVED_ENGINE_FIELD}")


def serving_engine_mismatch(a: StoreServingEngine, b: StoreServingEngine) -> Optional[str]:
    """Why two stores may NOT be pooled BY ENGINE — ``None`` when either states
    nothing (not a served store) or both resolve to one engine; else the
    cross-engine refusal, naming a lens-by-era side as such. The companion of
    :func:`reduction_mode_mismatch`, which sees only the tinycap route block."""
    if a.engine is None or b.engine is None or a.engine == b.engine:
        return None
    lens = a if a.engine == SERVING_ENGINE_LENS else b
    return (f"{SERVED_ENGINE_FIELD} {a.engine!r} vs {b.engine!r} — different serving engines: one store is a "
            f"{SERVING_ENGINE_LORA_NATIVE!r} store (a PEFT adapter at every position, no lens hook) and the other a lens "
            "store" + (" (by era: it states no engine under any spelling)" if lens.stated is None else "")
            + "; a comparison across engines measures the engine as well as the intervention and is not poolable — "
            "compare within one engine (native-serving-default plan §1.3; review r1 finding g)")


#: the out-root NAMESPACE a NATIVE launch writes its stores under (``<gen root>/native/<model>/<cell>/thinking_<mode>``;
#: the tinycap launcher's defence in depth): a native run cannot land in a lens root by default
OUT_SUBDIR_NATIVE = "native"


def gen_root_for_engine(root: str, serving_engine: Optional[str]) -> str:
    """The out root a launch under ``serving_engine`` plans its cell out dirs from
    (``cell_out_dir(gen_root_for_engine(root, engine), cell, mode)``): ``root`` itself for
    the lens (every historical path, byte-identical; ``None`` reads as the lens by era) and
    ``<root>/native`` for :data:`SERVING_ENGINE_LORA_NATIVE`. THE ONE derivation, shared by
    the tinycap launcher (``native_gen_root``) and the sandbox watcher's ``cell_out_dir``
    (deriving the lens root for a native run never finds its attempt pointers and leaves
    orphan sandboxes to their timeout). An unknown engine refuses."""
    if serving_engine in (None, SERVING_ENGINE_LENS):
        return str(root).rstrip("/")
    if serving_engine == SERVING_ENGINE_LORA_NATIVE:
        return f"{str(root).rstrip('/')}/{OUT_SUBDIR_NATIVE}"
    raise ValueError(f"serving_engine must be one of {list(SERVING_ENGINES)} (or None for the lens by era), got {serving_engine!r}")
LENS_STACKED_REDUCTIONS_ENV = "SISTEER_LENS_STACKED_REDUCTIONS"
#: The parser's table (E29 / PW18b), exactly: the empty string stands for an
#: UNSET variable too (:func:`reduction_mode_from_env`).
REDUCTION_MODE_ENV_VALUES: Mapping[str, str] = {
    "": REDUCTION_MODE_STACKED, "1": REDUCTION_MODE_STACKED, "stacked": REDUCTION_MODE_STACKED,
    "0": REDUCTION_MODE_PER_ROW, "per_row": REDUCTION_MODE_PER_ROW, "off": REDUCTION_MODE_PER_ROW,
}
#: What the parser makes of an UNSET switch: STACKED, since the landing (E46).
#: This is the ONE line E31 said would move, and the only one that did: a
#: worker spawned from a tree containing the landing with the switch unset
#: serves stacked, so an expectation of per_row here would refuse every such
#: standup. Distinct from :data:`REDUCTION_MODE_DEFAULT` (what a keyless
#: SERVER served — pre-landing, per_row forever) and from
#: :data:`REDUCTION_MODE_LAUNCHER_DEFAULT` (what the launcher ASKS for);
#: neither moved.
REDUCTION_MODE_ENV_UNSET = REDUCTION_MODE_STACKED
#: The launcher's ``--reduction-mode`` default. Still per_row after the
#: landing (E46): the wave in flight is per_row on its own frozen pre-landing
#: tree, and the launcher states the value explicitly either way, so this
#: default is a choice about what to ASK FOR and not a reading of any tree.
REDUCTION_MODE_LAUNCHER_DEFAULT = REDUCTION_MODE_PER_ROW


def resolve_reduction_mode(*stated: Optional[str], sources: Sequence[str] = ()) -> str:
    """The ATTESTED reduction mode from the values the record / identity block
    STATE (``None`` = the key is absent there): every stated value must be one
    of :data:`REDUCTION_MODES` and all stated values must agree (two sources
    disagreeing is a refusal naming both, never a preference); no stated value
    at all is :data:`REDUCTION_MODE_DEFAULT` — the server itself reports no
    key, i.e. a pre-landing server (E29). ``sources`` names the origins for
    the refusal text. Environment expectations never enter here; they are
    held to the result by :func:`check_reduction_mode_expectation`."""
    names = list(sources) + [f"source {i}" for i in range(len(sources), len(stated))]
    present = [(n, v) for n, v in zip(names, stated) if v is not None]
    for n, v in present:
        if not isinstance(v, str) or v not in REDUCTION_MODES:
            raise ValueError(
                f"{n} states {PROXY_IDENTITY_REDUCTION_MODE}={v!r}, not one of "
                f"{list(REDUCTION_MODES)} — refusing to record an unknown lens reduction "
                "mode as served identity")
    if len({v for _, v in present}) > 1:
        raise ValueError(
            "the lens reduction mode is stated inconsistently: "
            + "; ".join(f"{n}={v!r}" for n, v in present)
            + " — the record does not vouch for the proxy answering; refusing")
    return present[0][1] if present else REDUCTION_MODE_DEFAULT


def reduction_mode_from_env(environ: Mapping[str, str]) -> str:
    """The reduction mode a server derives from ``environ`` — the parser's
    rule, exactly (E29 / PW18b; the unset branch flipped by E46):
    :data:`LENS_STACKED_REDUCTIONS_ENV` unset or empty -> STACKED (the landing
    is on main and merged here, so that is what a worker spawned from this
    tree serves — ``lens_adapters.parse_reduction_mode`` agrees); ``0`` /
    ``per_row`` / ``off`` -> per_row; ``1`` / ``stacked`` -> stacked; anything
    else refuses (a launcher must never derive an expectation from a switch it
    cannot read — including the ``true`` / ``on`` / ``yes`` / ``all`` spellings
    the serving parser accepts and this one does not, which refuse loudly here
    rather than yielding a wrong expectation). This is an
    EXPECTATION of what the server will attest — a pre-landing server attests
    nothing (= per_row) whatever the environment says, so the expectation is
    always held to the attestation (:func:`check_reduction_mode_expectation`),
    never recorded on its own."""
    raw = environ.get(LENS_STACKED_REDUCTIONS_ENV)
    if raw is None:
        return REDUCTION_MODE_ENV_UNSET
    try:
        return REDUCTION_MODE_ENV_VALUES[raw]
    except (KeyError, TypeError):
        raise ValueError(
            f"{LENS_STACKED_REDUCTIONS_ENV}={raw!r} is not one of "
            f"{sorted(v for v in REDUCTION_MODE_ENV_VALUES if v)} (or unset / empty = per_row) "
            "— the lens reduction mode this standup would serve cannot be derived (the "
            "worker refuses this value at import); refusing") from None


def check_reduction_mode_expectation(attested: str, expected: Optional[str], *,
                                     expected_source: str = LENS_STACKED_REDUCTIONS_ENV,
                                     keyless: bool = False) -> str:
    """Hold an EXPECTATION (``None`` = none stated) to the ATTESTED mode (E29):
    equal, or no expectation, returns ``attested``; a disagreement is a
    ``ValueError`` naming both — never a value recorded into identity.
    ``keyless`` says the server reported no key at all (a pre-landing server,
    attested = per_row by :func:`resolve_reduction_mode`): that equals per_row
    only when per_row was expected — an expectation of stacked against a
    keyless server refuses, naming the server as pre-landing."""
    if attested not in REDUCTION_MODES:
        raise ValueError(
            f"attested lens reduction mode {attested!r} is not one of {list(REDUCTION_MODES)}")
    if expected is not None and expected != attested:
        if keyless:
            raise ValueError(
                f"{expected_source} expects {PROXY_IDENTITY_REDUCTION_MODE}={expected!r} but the "
                "server attests no reduction mode at all — a pre-landing server, which serves "
                f"only {REDUCTION_MODE_PER_ROW!r}; state {LENS_STACKED_REDUCTIONS_ENV}="
                f"{REDUCTION_MODE_PER_ROW} (the launcher: --reduction-mode {REDUCTION_MODE_PER_ROW}) "
                "for this tree, or launch a sha that serves stacked; refusing rather than "
                "recording either into identity")
        raise ValueError(
            f"the server attests {PROXY_IDENTITY_REDUCTION_MODE}={attested!r} but "
            f"{expected_source} expects {expected!r} — the standup did not serve the mode "
            "the environment asked for; refusing rather than recording either into identity")
    return attested


