# evidence.json (E1 three-legged control)                                      #
# --------------------------------------------------------------------------- #

BITES_LEGS: Tuple[str, ...] = ("steered", "scale0", "scale0_repeat")
BITES_PROBE_ITEMS = 8   # == served_capability_run.LOGPROB_BITES_PROBES

# --------------------------------------------------------------------------- #
# geometry sub-entries                                                         #
