class SubsetPinError(ValueError):
    """A pin file that does not regenerate from its own recorded rule, or
    whose ``seed`` / ``n`` / ``of`` drifted from the contracts — refused,
    never read around: a leg over a moved item set is another instrument."""


def hash_order(ids: Sequence[str], *, seed: int = SUBSET_SEED) -> List[str]:
    """``ids`` sorted by ``sha256(f"{seed}:{id}")`` — the seeded ordering both
    subsets are drawn with. Pure, interpreter-independent (fixed by the standard
    it names), and total: duplicate ids refuse (a population is a set)."""
    if isinstance(seed, bool) or not isinstance(seed, int):
        raise ValueError(f"hash_order: seed must be an int, got {seed!r}")
    ids = [str(i) for i in ids]
    if len(set(ids)) != len(ids):
        dup = sorted({i for i in ids if ids.count(i) > 1})[:5]
        raise ValueError(f"hash_order: duplicate ids {dup} — a population is a set")
    return sorted(ids, key=lambda i: hashlib.sha256(f"{seed}:{i}".encode()).hexdigest())


def hamilton_allocation(counts: Mapping[str, int], n: int, *, floor: int = 1) -> Dict[str, int]:
    """Largest-remainder (Hamilton) seats proportional to ``counts`` with a
    floor per category: ``q_c = n * n_c / N``, ``a_c = max(floor, floor(q_c))``,
    the remaining seats one each to the categories ordered by
    ``(remainder = q_c - floor(q_c) DESCENDING, category name ASCENDING)`` —
    the deterministic tie-break (several BFCL categories share a size, so it
    is load-bearing). Refuses when the floors alone exceed ``n``,
    or a seat count exceeds its category's size. Insensitive to the input's
    order: the result is sorted by category name."""
    if isinstance(n, bool) or not isinstance(n, int) or n < 1:
        raise ValueError(f"hamilton_allocation: n must be a positive int, got {n!r}")
    cats = {str(k): int(v) for k, v in counts.items()}
    if any(v < 1 for v in cats.values()):
        raise ValueError("hamilton_allocation: every category must be non-empty")
    total = sum(cats.values())
    quotas = {c: n * cats[c] / total for c in cats}
    seats = {c: max(int(floor), math.floor(quotas[c])) for c in cats}
    if sum(seats.values()) > n:
        raise ValueError(
            f"hamilton_allocation: the floors alone allocate {sum(seats.values())} > {n} seats "
            f"over {len(cats)} categories")
    remaining = n - sum(seats.values())
    order = sorted(cats, key=lambda c: (-(quotas[c] - math.floor(quotas[c])), c))
    for c in order[:remaining]:
        seats[c] += 1
    over = {c: (seats[c], cats[c]) for c in cats if seats[c] > cats[c]}
    if over:
        raise ValueError(f"hamilton_allocation: seats exceed the category size: {over}")
    assert sum(seats.values()) == n
    return {c: seats[c] for c in sorted(seats)}


def bcb_select(ids: Sequence[str], hard_ids: Sequence[str], *, n: int = BCB_SUBSET_N,
               seed: int = SUBSET_SEED) -> List[str]:
    """The BigCodeBench rule: population = the complete split's ids minus the
    Hard ids; ``hash_order(population, seed)[:n]``; reported sorted by numeric
    suffix (``BigCodeBench/17`` < ``BigCodeBench/120``). Refuses a Hard id
    outside the split, a population short of ``n``, or a malformed id."""
    ids = [str(i) for i in ids]
    hard = {str(i) for i in hard_ids}
    if not hard <= set(ids):
        raise ValueError(f"bcb_select: Hard ids outside the complete split: {sorted(hard - set(ids))[:5]}")
    population = [i for i in ids if i not in hard]
    if len(population) < n:
        raise ValueError(f"bcb_select: population {len(population)} < n {n}")
    picked = hash_order(population, seed=seed)[:n]
    return sorted(picked, key=lambda i: int(bcb_log_id(i)))


def bfcl_select(population: Mapping[str, Sequence[str]], *, n: int = BFCL_SUBSET_N,
                seed: int = SUBSET_SEED) -> Tuple[List[str], Dict[str, int]]:
    """The BFCL rule: seats per category by :func:`hamilton_allocation` (floor
    1) over the category sizes; within a category ``hash_order(ids, seed)[:a_c]``.
    Returns ``(ids in category-then-hash order, per_category seats)``. Every id
    must live in exactly one category (refused otherwise)."""
    pop = {str(c): [str(i) for i in v] for c, v in population.items()}
    flat = [i for v in pop.values() for i in v]
    if len(set(flat)) != len(flat):
        raise ValueError("bfcl_select: an id appears in more than one category")
    seats = hamilton_allocation({c: len(v) for c, v in pop.items()}, n)
    ids: List[str] = []
    for c in sorted(pop):
        ids.extend(hash_order(pop[c], seed=seed)[:seats[c]])
    return ids, seats


def bcb_select_full(ids: Sequence[str], hard_ids: Sequence[str]) -> List[str]:
    """The BigCodeBench FULL rule (capeval-full-tasks): the whole complete
    split, Hard INCLUDED, no seed — every id, reported sorted by the numeric
    suffix. Refuses a Hard id outside the split, a duplicate, or a malformed
    id (the same vocabulary check as :func:`bcb_select`)."""
    ids = [str(i) for i in ids]
    hard = {str(i) for i in hard_ids}
    if len(set(ids)) != len(ids):
        raise ValueError("bcb_select_full: duplicate ids — a population is a set")
    if not hard <= set(ids):
        raise ValueError(f"bcb_select_full: Hard ids outside the complete split: {sorted(hard - set(ids))[:5]}")
    return sorted(ids, key=lambda i: int(bcb_log_id(i)))


def bfcl_select_full(population: Mapping[str, Sequence[str]]) -> Tuple[List[str], Dict[str, int]]:
    """The BFCL FULL rule (capeval-full-tasks): every id of every category, no
    seed — reported in category-name order, within a category in the
    population's RECORDED order (inspect_evals' loader order at the pinned
    commit); ``per_category`` = the population counts. Every id must live in
    exactly one category (refused otherwise, as :func:`bfcl_select`)."""
    pop = {str(c): [str(i) for i in v] for c, v in population.items()}
    flat = [i for v in pop.values() for i in v]
    if len(set(flat)) != len(flat):
        raise ValueError("bfcl_select_full: an id appears in more than one category")
    if any(not v for v in pop.values()):
        raise ValueError("bfcl_select_full: every category must be non-empty")
    ids: List[str] = []
    for c in sorted(pop):
        ids.extend(pop[c])
    return ids, {c: len(pop[c]) for c in sorted(pop)}


def bcb_pinned_id(log_id: str) -> str:
    """``"17"`` (Inspect's stringified integer sample id, the row's ``item_id``)
    -> ``"BigCodeBench/17"`` (the pinned id). Refuses anything but a non-negative
    integer string."""
    s = str(log_id)
    if not s.isdigit():
        raise ValueError(f"bcb_pinned_id: {log_id!r} is not a BigCodeBench sample id (an int string)")
    return f"BigCodeBench/{int(s)}"


def bcb_log_id(pinned_id: str) -> str:
    """``"BigCodeBench/17"`` -> ``"17"`` — the id the rows and the Inspect log
    carry (``str(int(task_id.split('/')[-1]))``). Refuses a foreign prefix."""
    s = str(pinned_id)
    prefix, sep, tail = s.partition("/")
    if prefix != "BigCodeBench" or not sep or not tail.isdigit():
        raise ValueError(f"bcb_log_id: {pinned_id!r} is not a BigCodeBench task id")
    return str(int(tail))


def ids_sha256(ids: Sequence[str]) -> str:
    """The sha256 of the canonical JSON of an id list, in the given order —
    the digest the item-set identity and the pin's ``source_sha256`` carry."""
    return hashlib.sha256(json.dumps([str(i) for i in ids], separators=(",", ":")).encode()).hexdigest()


def item_set_identity(pin: Mapping[str, object]) -> Dict[str, object]:
    """The HASHED item-set spec of a pinned leg (:data:`IDENTITY_KEY_BCB_ITEM_SET`
    / :data:`IDENTITY_KEY_BFCL_ITEM_SET`): ``{seed, n, of, ids_sha256}`` over the
    pin's ids in pin order — pure, launcher-derivable, and small."""
    ids = list(pin["ids"])
    seed = pin["seed"]
    return {"seed": (None if seed is None else int(seed)), "n": int(pin["n"]), "of": int(pin["of"]),
            "ids_sha256": ids_sha256(ids)}


def bcb_lib_families(repo_root: str | Path) -> Dict[str, str]:
    """The TOTAL ``lib -> family`` map (:data:`BCB_LIB_FAMILIES_PATH`), verified
    to be a non-empty mapping of strings for the BigCodeBench task."""
    path = Path(repo_root) / BCB_LIB_FAMILIES_PATH
    if not path.is_file():
        raise SubsetPinError(f"{path} is missing")
    doc = json.loads(path.read_text(encoding="utf-8"))
    fams = doc.get("families") if isinstance(doc, Mapping) else None
    if (not isinstance(doc, Mapping) or doc.get("schema") != SUBSET_PIN_SCHEMA or doc.get("task") != "bigcodebench_200"
            or not isinstance(fams, Mapping) or not fams
            or not all(isinstance(k, str) and isinstance(v, str) and k and v for k, v in fams.items())):
        raise SubsetPinError(f"{BCB_LIB_FAMILIES_PATH}: families must be a non-empty {{lib: family}} map of strings "
                             f"(schema {SUBSET_PIN_SCHEMA}, task bigcodebench_200)")
    return dict(fams)


def bcb_per_family_counts(libs_by_id: Mapping[str, Sequence[str]], families: Mapping[str, str]
                          ) -> Dict[str, int]:
    """Multi-label per-family item counts: an item counts ONCE under every
    family any of its libs maps to; an item with no libs counts under
    ``stdlib_only``. An unmapped lib refuses (the map is total by contract)."""
    out: Dict[str, int] = {}
    for item, libs in libs_by_id.items():
        fams = set()
        for lib in libs:
            if lib not in families:
                raise SubsetPinError(f"lib {lib!r} of {item} has no family in {BCB_LIB_FAMILIES_PATH}")
            fams.add(families[lib])
        if not fams:
            fams.add("stdlib_only")
        for f in fams:
            out[f] = out.get(f, 0) + 1
    return dict(sorted(out.items()))


def _load_pin(path: Path, *, task: str, n: int, of: int, seed: int,
              extra_fields: Sequence[str] = ()) -> Dict[str, object]:
    if not path.is_file():
        raise SubsetPinError(f"pin {path} is missing — scripts/capeval_subsets.py --build writes it")
    doc = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(doc, Mapping):
        raise SubsetPinError(f"pin {path}: not an object ({type(doc).__name__})")
    # the required set first, then the task's EXACT key set — an extra key can
    # neither pass nor mask a missing one
    missing = sorted(set(SUBSET_PIN_FIELDS) - set(doc))
    if missing:
        raise SubsetPinError(f"pin {path}: missing {missing} of the contract's {list(SUBSET_PIN_FIELDS)}")
    want = set(SUBSET_PIN_FIELDS) | set(extra_fields)
    if set(doc) != want:
        raise SubsetPinError(f"pin {path}: keys {sorted(doc)} != exactly {sorted(want)} "
                             f"(extra {sorted(set(doc) - want)}, missing {sorted(want - set(doc))})")
    for key in ("generated_by", "generated_at", "rule"):
        if not isinstance(doc[key], str) or not doc[key]:
            raise SubsetPinError(f"pin {path}: {key} must be a non-empty string")
    if not isinstance(doc["dataset"], Mapping) or not isinstance(doc["source_sha256"], Mapping):
        raise SubsetPinError(f"pin {path}: dataset / source_sha256 must be objects")
    if not all(isinstance(k, str) and isinstance(v, str) and v for k, v in doc["source_sha256"].items()):
        raise SubsetPinError(f"pin {path}: source_sha256 must map names to digest strings")
    if doc.get("schema") != SUBSET_PIN_SCHEMA or doc.get("task") != task:
        raise SubsetPinError(f"pin {path}: schema {doc.get('schema')!r} / task {doc.get('task')!r} "
                             f"!= ({SUBSET_PIN_SCHEMA}, {task!r})")
    for key, want in (("seed", seed), ("n", n), ("of", of)):
        if key not in doc or doc.get(key) != want:
            raise SubsetPinError(f"pin {path}: {key} {doc.get(key)!r} != the contracts' {want} — a re-pin "
                                 "is a new instrument and lands with a deliberate contracts change")
    ids = doc["ids"]
    if not isinstance(ids, list) or len(ids) != n or len(set(ids)) != n or not all(isinstance(i, str) for i in ids):
        raise SubsetPinError(f"pin {path}: ids is not a list of {n} distinct id strings")
    return dict(doc)


def load_bcb_pin(repo_root: str | Path) -> Dict[str, object]:
    """The BigCodeBench pin, VERIFIED: the contracts' seed / n / of, exactly
    ``n`` distinct ids, none Hard (the pin records the Hard ids under
    ``population["hard_ids"]``), and the ids REGENERATE from the recorded
    population through :func:`bcb_select`. Refuses (:class:`SubsetPinError`)
    otherwise."""
    doc = _load_pin(Path(repo_root) / BCB_PIN_PATH, task="bigcodebench_200",
                    n=BCB_SUBSET_N, of=BCB_NONHARD_N, seed=SUBSET_SEED, extra_fields=SUBSET_PIN_BCB_EXTRA_FIELDS)
    # the dataset block: the pinned repos, revisions, split and counts, exactly
    want_dataset = {"complete": {"repo_id": BCB_DATASET, "revision": BCB_DATASET_REVISION, "split": BCB_SPLIT,
                                 "n": BCB_FULL_N},
                    "hard": {"repo_id": BCB_HARD_DATASET, "revision": BCB_HARD_DATASET_REVISION, "split": BCB_SPLIT,
                             "n": BCB_HARD_N}}
    if {k: dict(v) for k, v in doc["dataset"].items() if isinstance(v, Mapping)} != want_dataset:
        raise SubsetPinError(f"{BCB_PIN_PATH}: dataset {doc['dataset']} != the contracts' {want_dataset}")
    if set(doc["source_sha256"]) != set(BCB_PIN_SOURCE_FIELDS) or not all(
            is_sha256_hex(doc["source_sha256"][k]) for k in BCB_PIN_SOURCE_FIELDS):
        raise SubsetPinError(f"{BCB_PIN_PATH}: source_sha256 must carry exactly {list(BCB_PIN_SOURCE_FIELDS)} as sha256 hex")
    if doc["per_category"] != {}:
        raise SubsetPinError(f"{BCB_PIN_PATH}: per_category is {{}} for BigCodeBench (no category seats)")
    pop = doc["population"]
    if not isinstance(pop, Mapping) or set(pop) != {"ids", "hard_ids"}:
        raise SubsetPinError(f"{BCB_PIN_PATH}: population must carry exactly ids + hard_ids")
    if (not isinstance(pop["ids"], list) or not isinstance(pop["hard_ids"], list)
            or len(pop["ids"]) != BCB_FULL_N or len(set(pop["ids"])) != BCB_FULL_N
            or len(pop["hard_ids"]) != BCB_HARD_N or len(set(pop["hard_ids"])) != BCB_HARD_N):
        raise SubsetPinError(f"{BCB_PIN_PATH}: population {len(pop['ids'])} / hard {len(pop['hard_ids'])} != "
                             f"{BCB_FULL_N} / {BCB_HARD_N} distinct ids")
    if not set(pop["hard_ids"]) <= set(pop["ids"]):
        raise SubsetPinError(f"{BCB_PIN_PATH}: hard_ids are not a subset of the complete split's ids")
    regen = bcb_select(pop["ids"], pop["hard_ids"], n=BCB_SUBSET_N, seed=SUBSET_SEED)
    if regen != list(doc["ids"]):
        raise SubsetPinError(f"{BCB_PIN_PATH}: the pinned ids do not regenerate from the recorded rule")
    if set(doc["ids"]) & set(pop["hard_ids"]):
        raise SubsetPinError(f"{BCB_PIN_PATH}: a Hard id is pinned")
    for i in doc["ids"]:
        bcb_log_id(i)                                        # the pinned vocabulary, or refuse
    # the per-item libraries: exactly the selected ids, lists of strings, every
    # lib in the total family map, and the per-family counts recomputing
    libs = doc["libs_by_id"]
    if not isinstance(libs, Mapping) or set(libs) != set(doc["ids"]):
        raise SubsetPinError(f"{BCB_PIN_PATH}: libs_by_id keys != the pinned ids")
    if not all(isinstance(v, list) and all(isinstance(x, str) and x for x in v) for v in libs.values()):
        raise SubsetPinError(f"{BCB_PIN_PATH}: libs_by_id values must be lists of library names")
    families = bcb_lib_families(repo_root)
    counts = bcb_per_family_counts(libs, families)          # refuses an unmapped lib
    if not isinstance(doc["per_family"], Mapping) or {k: int(v) for k, v in doc["per_family"].items()} != counts:
        raise SubsetPinError(f"{BCB_PIN_PATH}: per_family {doc['per_family']} does not recompute from libs_by_id "
                             f"through {BCB_LIB_FAMILIES_PATH} ({counts})")
    return doc


def load_bfcl_pin(repo_root: str | Path) -> Dict[str, object]:
    """The BFCL pin, VERIFIED: the contracts' seed / n / of, exactly ``n``
    distinct ids, and the ids + per-category seats REGENERATE from the recorded
    ``population`` (``{category_name: [ids]}``) through :func:`bfcl_select`."""
    doc = _load_pin(Path(repo_root) / BFCL_PIN_PATH, task="bfcl_200",
                    n=BFCL_SUBSET_N, of=BFCL_FULL_N, seed=SUBSET_SEED)
    # the dataset block: the loader, the repo at its pinned commit, the exact roster
    want_dataset = {"repo": BFCL_PIN_REPO, "commit": BFCL_GORILLA_COMMIT_FULL, "loader": BFCL_PIN_LOADER,
                    "categories": list(BFCL_CATEGORIES), "n": BFCL_FULL_N}
    if dict(doc["dataset"]) != want_dataset:
        raise SubsetPinError(f"{BFCL_PIN_PATH}: dataset {dict(doc['dataset'])} != the contracts' {want_dataset}")
    pop = doc["population"]
    if not isinstance(pop, Mapping) or set(pop) != set(BFCL_CATEGORIES):
        raise SubsetPinError(f"{BFCL_PIN_PATH}: population categories "
                             f"{sorted(pop) if isinstance(pop, Mapping) else pop!r} != the roster {list(BFCL_CATEGORIES)}")
    if not all(isinstance(v, list) and all(isinstance(i, str) and i for i in v) for v in pop.values()):
        raise SubsetPinError(f"{BFCL_PIN_PATH}: population values must be lists of id strings")
    flat = [i for v in pop.values() for i in v]
    if len(flat) != BFCL_FULL_N or len(set(flat)) != BFCL_FULL_N:
        raise SubsetPinError(f"{BFCL_PIN_PATH}: population is not {BFCL_FULL_N} distinct ids by category")
    if set(doc["source_sha256"]) != set(BFCL_PIN_SOURCE_FIELDS):
        raise SubsetPinError(f"{BFCL_PIN_PATH}: source_sha256 must carry exactly {list(BFCL_PIN_SOURCE_FIELDS)}")
    if doc["source_sha256"]["gorilla_commit"] != BFCL_GORILLA_COMMIT_FULL:
        raise SubsetPinError(f"{BFCL_PIN_PATH}: source_sha256.gorilla_commit {doc['source_sha256']['gorilla_commit']!r} "
                             f"!= the pinned {BFCL_GORILLA_COMMIT_FULL}")
    digest = hashlib.sha256(json.dumps({c: sorted(v) for c, v in pop.items()}, sort_keys=True).encode()).hexdigest()
    if doc["source_sha256"]["population_by_category"] != digest:
        raise SubsetPinError(f"{BFCL_PIN_PATH}: source_sha256.population_by_category does not recompute from the "
                             "recorded population")
    if not isinstance(doc["per_category"], Mapping) or set(doc["per_category"]) != set(BFCL_CATEGORIES):
        raise SubsetPinError(f"{BFCL_PIN_PATH}: per_category must seat exactly the roster {list(BFCL_CATEGORIES)}")
    ids, seats = bfcl_select(pop, n=BFCL_SUBSET_N, seed=SUBSET_SEED)
    if ids != list(doc["ids"]) or seats != {k: int(v) for k, v in doc["per_category"].items()}:
        raise SubsetPinError(f"{BFCL_PIN_PATH}: the pinned ids / seats do not regenerate from the recorded rule")
    return doc


def load_bcb_full_pin(repo_root: str | Path) -> Dict[str, object]:
    """The BigCodeBench FULL pin (capeval-full-tasks), VERIFIED: seed null, n =
    of = :data:`BCB_FULL_N`, the ids REGENERATE from the recorded population
    through :func:`bcb_select_full` (every complete-split id, Hard included,
    sorted by numeric suffix), the top-level ``hard_ids`` equal the
    population's, every lib mapped, the per-family counts recomputing. The
    same dataset block, digests and vocabulary checks as :func:`load_bcb_pin`."""
    path = Path(repo_root) / BCB_FULL_PIN_PATH
    doc = _load_pin(path, task=CONTROL_BIGCODEBENCH_FULL, n=BCB_FULL_N, of=BCB_FULL_N, seed=FULL_PIN_SEED,
                    extra_fields=SUBSET_PIN_BCB_FULL_EXTRA_FIELDS)
    want_dataset = {"complete": {"repo_id": BCB_DATASET, "revision": BCB_DATASET_REVISION, "split": BCB_SPLIT,
                                 "n": BCB_FULL_N},
                    "hard": {"repo_id": BCB_HARD_DATASET, "revision": BCB_HARD_DATASET_REVISION, "split": BCB_SPLIT,
                             "n": BCB_HARD_N}}
    if {k: dict(v) for k, v in doc["dataset"].items() if isinstance(v, Mapping)} != want_dataset:
        raise SubsetPinError(f"{BCB_FULL_PIN_PATH}: dataset {doc['dataset']} != the contracts' {want_dataset}")
    if set(doc["source_sha256"]) != set(BCB_PIN_SOURCE_FIELDS) or not all(
            is_sha256_hex(doc["source_sha256"][k]) for k in BCB_PIN_SOURCE_FIELDS):
        raise SubsetPinError(f"{BCB_FULL_PIN_PATH}: source_sha256 must carry exactly {list(BCB_PIN_SOURCE_FIELDS)} as sha256 hex")
    if doc["per_category"] != {}:
        raise SubsetPinError(f"{BCB_FULL_PIN_PATH}: per_category is {{}} for BigCodeBench (no category seats)")
    pop = doc["population"]
    if not isinstance(pop, Mapping) or set(pop) != {"ids", "hard_ids"}:
        raise SubsetPinError(f"{BCB_FULL_PIN_PATH}: population must carry exactly ids + hard_ids")
    if (not isinstance(pop["ids"], list) or not isinstance(pop["hard_ids"], list)
            or len(pop["ids"]) != BCB_FULL_N or len(set(pop["ids"])) != BCB_FULL_N
            or len(pop["hard_ids"]) != BCB_HARD_N or len(set(pop["hard_ids"])) != BCB_HARD_N):
        raise SubsetPinError(f"{BCB_FULL_PIN_PATH}: population {len(pop['ids'])} / hard {len(pop['hard_ids'])} != "
                             f"{BCB_FULL_N} / {BCB_HARD_N} distinct ids")
    if not set(pop["hard_ids"]) <= set(pop["ids"]):
        raise SubsetPinError(f"{BCB_FULL_PIN_PATH}: hard_ids are not a subset of the complete split's ids")
    if list(doc["hard_ids"]) != list(pop["hard_ids"]):
        raise SubsetPinError(f"{BCB_FULL_PIN_PATH}: the top-level hard_ids != population.hard_ids")
    regen = bcb_select_full(pop["ids"], pop["hard_ids"])
    if regen != list(doc["ids"]):
        raise SubsetPinError(f"{BCB_FULL_PIN_PATH}: the pinned ids do not regenerate from the recorded rule")
    for i in doc["ids"]:
        bcb_log_id(i)
    libs = doc["libs_by_id"]
    if not isinstance(libs, Mapping) or set(libs) != set(doc["ids"]):
        raise SubsetPinError(f"{BCB_FULL_PIN_PATH}: libs_by_id keys != the pinned ids")
    if not all(isinstance(v, list) and all(isinstance(x, str) and x for x in v) for v in libs.values()):
        raise SubsetPinError(f"{BCB_FULL_PIN_PATH}: libs_by_id values must be lists of library names")
    families = bcb_lib_families(repo_root)
    counts = bcb_per_family_counts(libs, families)
    if not isinstance(doc["per_family"], Mapping) or {k: int(v) for k, v in doc["per_family"].items()} != counts:
        raise SubsetPinError(f"{BCB_FULL_PIN_PATH}: per_family {doc['per_family']} does not recompute from libs_by_id "
                             f"through {BCB_LIB_FAMILIES_PATH} ({counts})")
    return doc


def load_bfcl_full_pin(repo_root: str | Path) -> Dict[str, object]:
    """The BFCL FULL pin (capeval-full-tasks), VERIFIED: seed null, n = of =
    :data:`BFCL_FULL_N`, the ids + per-category counts REGENERATE from the
    recorded ``population`` through :func:`bfcl_select_full`; the same dataset
    block, roster, commit and population digest checks as :func:`load_bfcl_pin`."""
    doc = _load_pin(Path(repo_root) / BFCL_FULL_PIN_PATH, task=CONTROL_BFCL_FULL,
                    n=BFCL_FULL_N, of=BFCL_FULL_N, seed=FULL_PIN_SEED)
    want_dataset = {"repo": BFCL_PIN_REPO, "commit": BFCL_GORILLA_COMMIT_FULL, "loader": BFCL_PIN_LOADER,
                    "categories": list(BFCL_CATEGORIES), "n": BFCL_FULL_N}
    if dict(doc["dataset"]) != want_dataset:
        raise SubsetPinError(f"{BFCL_FULL_PIN_PATH}: dataset {dict(doc['dataset'])} != the contracts' {want_dataset}")
    pop = doc["population"]
    if not isinstance(pop, Mapping) or set(pop) != set(BFCL_CATEGORIES):
        raise SubsetPinError(f"{BFCL_FULL_PIN_PATH}: population categories "
                             f"{sorted(pop) if isinstance(pop, Mapping) else pop!r} != the roster {list(BFCL_CATEGORIES)}")
    if not all(isinstance(v, list) and all(isinstance(i, str) and i for i in v) for v in pop.values()):
        raise SubsetPinError(f"{BFCL_FULL_PIN_PATH}: population values must be lists of id strings")
    flat = [i for v in pop.values() for i in v]
    if len(flat) != BFCL_FULL_N or len(set(flat)) != BFCL_FULL_N:
        raise SubsetPinError(f"{BFCL_FULL_PIN_PATH}: population is not {BFCL_FULL_N} distinct ids by category")
    if set(doc["source_sha256"]) != set(BFCL_PIN_SOURCE_FIELDS):
        raise SubsetPinError(f"{BFCL_FULL_PIN_PATH}: source_sha256 must carry exactly {list(BFCL_PIN_SOURCE_FIELDS)}")
    if doc["source_sha256"]["gorilla_commit"] != BFCL_GORILLA_COMMIT_FULL:
        raise SubsetPinError(f"{BFCL_FULL_PIN_PATH}: source_sha256.gorilla_commit {doc['source_sha256']['gorilla_commit']!r} "
                             f"!= the pinned {BFCL_GORILLA_COMMIT_FULL}")
    digest = hashlib.sha256(json.dumps({c: sorted(v) for c, v in pop.items()}, sort_keys=True).encode()).hexdigest()
    if doc["source_sha256"]["population_by_category"] != digest:
        raise SubsetPinError(f"{BFCL_FULL_PIN_PATH}: source_sha256.population_by_category does not recompute from the "
                             "recorded population")
    if not isinstance(doc["per_category"], Mapping) or set(doc["per_category"]) != set(BFCL_CATEGORIES):
        raise SubsetPinError(f"{BFCL_FULL_PIN_PATH}: per_category must count exactly the roster {list(BFCL_CATEGORIES)}")
    ids, counts = bfcl_select_full(pop)
    if ids != list(doc["ids"]) or counts != {k: int(v) for k, v in doc["per_category"].items()}:
        raise SubsetPinError(f"{BFCL_FULL_PIN_PATH}: the pinned ids / per-category counts do not regenerate from the "
                             "recorded rule")
    return doc

# --------------------------------------------------------------------------- #
# the BigCodeBench execution sandbox                                           #
# --------------------------------------------------------------------------- #

#: inspect_evals 0.18.0's own ``bigcodebench/compose.yaml`` image, by digest —
#: the ONE image every BigCodeBench verdict of this lane executes in. HASHED
#: (:func:`bcb_sandbox_identity`): a different image is a different verifier.
BCB_SANDBOX_IMAGE = ("ghcr.io/generality-labs/inspect-eval-bigcodebench:2026-07-28@sha256:"
                     "d7c88bf92782a7486d64bc1d07cd38ba9e735b5f58235fc0c0f36f8f692a1cfe")
#: The Inspect sandbox provider the thin task names: the in-repo subclass of
#: inspect-sandboxes' ``modal`` provider that creates every sandbox with the
#: OWNER tuple in its create-time tags (``sisteer.capeval.tiers.sandbox_owned``).
BCB_SANDBOX_PROVIDER = "modal_owned"
#: What the compose declares per sandbox (1 cpu, 0.5 GB, network none) — the
#: provider reads the compose, these are the values the thin task ASSERTS.
BCB_SANDBOX_RESOURCES: Mapping[str, object] = {"cpu": 1.0, "memory_mib": 512, "block_network": True}
#: The scorer's per-item ``exec`` timeout (inspect_evals' ``VERIFY_TIMEOUT``);
#: the provider re-executes on timeout (``[30, 30, 30]`` s), so a timed-out
#: verification costs up to ~90 s before the scorer files ``Verification timed
#: out.``. HASHED: a longer timeout passes more items.
BCB_VERIFY_TIMEOUT_S = 30
#: The sandbox's own lifetime (provider default 86,400 s): 3 h bounds a leak
#: from a hard-killed container to ≤ S × 3 h × ($0.142 + $0.012)/h. UNHASHED.
BCB_SANDBOX_TIMEOUT_S = 10_800
#: inspect-sandboxes' constant Modal app the sandboxes are created under
#: (``App.lookup(name, create_if_missing=True)`` from ANY client resolves the
#: same deployed app in the environment — the watcher lists by it).
BCB_SANDBOX_APP_NAME = "inspect_modal_sandbox"
#: The BigCodeBench row's three ``extra_json`` facts (beside INSPECT_EXTRA_FIELDS):
#: ``code_source`` — which of the stock ``find_code`` fallbacks produced the
#: scored code (BCB_CODE_SOURCES; a formatting DIAGNOSTIC, never
#: ``unparseable``); ``sandbox_status`` — ``ok`` (the verifier ran to a
#: verdict) | ``verify_timeout`` (the verifier's stderr was exactly
#: "Verification timed out."), classified by reconstructing the pinned scorer's
#: exact explanation grammar; ``verifier_explanation`` — the stderr tail of an
#: incorrect verdict (null when correct).
BCB_ROW_FACT_FIELDS: Tuple[str, ...] = ("code_source", "sandbox_status", "verifier_explanation")
BCB_CODE_SOURCES: Tuple[str, ...] = ("python_fence", "bare_fence", "whole_completion")
BCB_SANDBOX_STATUSES: Tuple[str, ...] = ("ok", "verify_timeout")
#: The two legs' thinking-OFF completion caps, stated ONCE here so
#: ``inspect_served.MAX_TOKENS_OFF`` (which reads them) and the launcher's dry
#: run (which has no inspect_ai to read the table from) name one number:
#: 4,096 for a whole function body with imports (the dataset's canonical
#: solutions run to ~850 chars at p95; the cap leaves room for a model that
#: explains first), 1,024 for one turn of tool calls (exactly ``bfcl``'s).
BCB200_MAX_TOKENS_OFF = 4096
BFCL200_MAX_TOKENS_OFF = 1024
#: capeval-full-tasks (2026-09-23): the FULL legs run at the SAME completion caps
#: — the cap is the instrument's (the eval's reference protocol), not the item
#: set's; a different cap would be a third instrument, not "the full set".
BCB_FULL_MAX_TOKENS_OFF = BCB200_MAX_TOKENS_OFF
BFCL_FULL_MAX_TOKENS_OFF = BFCL200_MAX_TOKENS_OFF
#: The two FULL row tasks (the harness limits below key on them).
FULL_ROW_TASKS: Tuple[str, ...] = (inspect_task(CONTROL_BIGCODEBENCH_FULL), inspect_task(CONTROL_BFCL_FULL))
#: The HARNESS limits a run filing a FULL leg carries — stated here, in config,
#: never widened silently on the 200 legs' constants (which stay exactly as they
#: are). Sized from the 200 legs' 45 measured containers (b64-capability-agentic-queue
#: ``logs/full_tasks/timing_inputs.md``, 2026-09-23) at 5.7x (BCB) / 19.9x (BFCL)
#: the item count. Measured per item at the served S (31 on the 4B rows): BCB
#: 0.35-1.25 s/item alone (qwen ``none`` ~550 completion tokens -> 0.35-0.48;
#: a long-completion PSR arm at 1.25; up to 2.9 when 5-12 BCB legs contend for the
#: sandbox-creation rate), BFCL 0.06-0.31 s/item; standup 4-17 min by family. So a
#: FULL pair per cell is ~0.5 h (qwen ``none``: 15 + 8 + 6 min) to ~1 h (a
#: long-completion arm: 15 + 24 + 18 min) alone, ~1.6 h at the worst measured
#: contention (2.9 x 1,140 + 0.31 x 3,981 s + standup); the 148 Hard items were
#: never timed (the 200 were drawn from the non-Hard 992) and are assumed no
#: worse than the long-completion arms.
#:
#: * ``driver_timeout_s`` — the container's ``subprocess.run(driver, timeout=)``
#:   bound (``tinycap_served.DRIVER_TIMEOUT_S`` = 6 h for every other run). The
#:   one limit that could BIND: a restart re-plans from the done markers, so the
#:   bound must cover ONE full pass with margin over the worst measured
#:   contention (~1.6 h) and the untimed Hard items: 8 h (5x the worst measured;
#:   NOT the 200 legs' 6 h, which already carries 3.7x — a full cell hung on a
#:   dead sandbox pool is 8 GPU-hours, so the bound is deliberately not 24 h).
#: * ``function_timeout_s`` — the Modal ``@app.function(timeout=)`` of the GPU
#:   worker (8 h for every other run). Must exceed the driver bound plus the
#:   standup and the sweep: 10 h; the container picks the ``*_full`` function
#:   variant when the configuration files a full leg (``configuration_function``).
#: * ``sandbox_timeout_s`` — UNCHANGED (:data:`BCB_SANDBOX_TIMEOUT_S`, 3 h): a
#:   sandbox lives for ONE sample (measured mean 6-26 s, max ~150 s = a 30 s
#:   verify timeout x the provider's 3 retries), never a leg; ``max_sandboxes`` =
#:   S bounds the live count, so the item count moves the sandbox-HOURS (5.7x)
#:   and nothing about a single sandbox's life.
#: * ``verify_timeout_s`` — UNCHANGED and HASHED (:data:`BCB_VERIFY_TIMEOUT_S`, 30 s):
#:   a longer verifier passes more items; changing it is another instrument.
#: * ``client_timeout_s`` — UNCHANGED (:data:`INSPECT_TIMEOUT_S`, 7,200 s): a
#:   per-REQUEST bound; the item count adds requests, not seconds per request
#:   (the longest measured request is a 4,096-token completion, minutes).
#: * ``max_sandboxes`` — UNCHANGED (= the served S per container): the
#:   per-container parallelism; the wall time scales as items / S. The
#:   account-wide sandbox-creation limit (Modal: ``Sandbox creation rate limit
#:   (5/s) exceeded``, verbatim in the 200 waves' driver_stderr.log, 8,515 retries
#:   across the 45 stores, 0 in any container whose BCB leg ran alone) binds ACROSS
#:   containers: one BCB leg alone creates ~S / service_s = 31 / 10.7 ~ 2.9/s
#:   (qwen), ~1.9/s (gemma), ~3.2/s (llama) at steady state, so TWO concurrent
#:   BCB legs saturate it and 5-12 concurrent legs ran 2-4x slower per item. The
#:   fan-out is therefore staggered so that at most ~2 BCB legs overlap (BFCL
#:   legs create no sandboxes and overlap freely); a full BCB leg is 7-25 min.
#: * ``gen.batch_size 8`` — NOT a served-path knob: the judged spool header's
#:   constant (``served_capability_run._gen_cfg``); the served fan-out's width is S.
FULL_DRIVER_TIMEOUT_S = 8 * 3600
FULL_FUNCTION_TIMEOUT_S = 10 * 3600
FULL_TASK_LIMITS: Mapping[str, Mapping[str, object]] = {
    inspect_task(CONTROL_BIGCODEBENCH_FULL): {
        "n_items": BCB_FULL_N, "scale_vs_200": BCB_FULL_N / BCB_SUBSET_N,
        "max_tokens_off": BCB_FULL_MAX_TOKENS_OFF,
        "driver_timeout_s": FULL_DRIVER_TIMEOUT_S, "function_timeout_s": FULL_FUNCTION_TIMEOUT_S,
        "sandbox_timeout_s": BCB_SANDBOX_TIMEOUT_S, "verify_timeout_s": BCB_VERIFY_TIMEOUT_S,
        "client_timeout_s": INSPECT_TIMEOUT_S, "max_sandboxes": "S (the served max_num_seqs)"},
    inspect_task(CONTROL_BFCL_FULL): {
        "n_items": BFCL_FULL_N, "scale_vs_200": BFCL_FULL_N / BFCL_SUBSET_N,
        "max_tokens_off": BFCL_FULL_MAX_TOKENS_OFF,
        "driver_timeout_s": FULL_DRIVER_TIMEOUT_S, "function_timeout_s": FULL_FUNCTION_TIMEOUT_S,
        "client_timeout_s": INSPECT_TIMEOUT_S},
}


def driver_timeout_s_for(row_tasks, default: int) -> int:
    """The container's driver ``subprocess`` timeout for a run over ``row_tasks``:
    :data:`FULL_DRIVER_TIMEOUT_S` when the run files a FULL leg
    (:func:`files_any_full_task`), else the caller's ``default`` (the 200 legs'
    and every other run's constant, untouched)."""
    return int(FULL_DRIVER_TIMEOUT_S) if files_any_full_task(row_tasks) else int(default)
#: The BigCodeBench summary's count fields (members of SUMMARY_PAYLOAD_FIELDS).
BCB_SUMMARY_COUNT_FIELDS: Tuple[str, ...] = (
    "n_sandbox_ok", "n_verify_timeout", "n_code_source_python_fence",
    "n_code_source_bare_fence", "n_code_source_whole_completion")


def bcb_sandbox_identity() -> Dict[str, object]:
    """The HASHED sandbox facts of a run that files BigCodeBench
    (:data:`IDENTITY_KEY_SANDBOX`): the image digest and the verifier timeout."""
    return {"image": BCB_SANDBOX_IMAGE, "verify_timeout_s": int(BCB_VERIFY_TIMEOUT_S)}


def bcb_sandbox_facts() -> Dict[str, object]:
    """EVERY sandbox fact of the BigCodeBench leg — what the task plan carries
    and the manifest's route block records (UNHASHED there; the two of
    :func:`bcb_sandbox_identity` are hashed separately): the provider, the
    image, the compose resources, the sandbox lifetime, the verifier timeout
    and the app."""
    return {"provider": BCB_SANDBOX_PROVIDER, "image": BCB_SANDBOX_IMAGE, **dict(BCB_SANDBOX_RESOURCES),
            "timeout_s": int(BCB_SANDBOX_TIMEOUT_S), "verify_timeout_s": int(BCB_VERIFY_TIMEOUT_S),
            "app_name": BCB_SANDBOX_APP_NAME, "binding_version": CPU_VERIFY_BINDING_VERSION}


# --------------------------------------------------------------------------- #
# the truncation LADDER's flags and identity values                            #
# --------------------------------------------------------------------------- #

#: The launcher's ``--cap-override <row_task>=<int>[,...]`` and the driver's
#: identical spelling: the 16,384 rung per fired row task. ``--item-selection
#: <ladder_selection.json>`` (launcher; slice C's ``tinycap_ladder.py select``
#: writes it) becomes ``--item-selection-json '<{row_task: {ids, n, ids_sha256}}>'``
#: on the driver (inline: the container has no path to the grading host file).
#: ``--ladder-rung L,S`` is the OPERATOR override of the rung probe (its
#: certificate says ``rung_source: operator``); ``--ladder-reprobe`` renames an
#: INVALID certificate aside and probes anew (an explicit, recorded act).
FLAG_CAP_OVERRIDE = "--cap-override"
FLAG_ITEM_SELECTION = "--item-selection"
FLAG_ITEM_SELECTION_JSON = "--item-selection-json"
FLAG_LADDER_RUNG = "--ladder-rung"
FLAG_LADDER_REPROBE = "--ladder-reprobe"
#: The row tasks the ladder may name (the two pinned legs, and nothing else).
LADDER_ROW_TASKS: Tuple[str, ...] = (inspect_task("bigcodebench_200"), inspect_task("bfcl_200"))
#: The ladder's ONE rung above the OFF caps: the truncation rule (1 %, then
#: the standing 16,384 ceiling — the SAME number as MATH-500's one-pass
#: completion cap; a cap, never a window; there is no rung above).
LADDER_CAP_TO = MATH500_MAX_TOKENS_DEFAULT


def parse_cap_overrides(spec: str) -> Dict[str, int]:
    """``"inspect/bigcodebench_200=<cap>,inspect/bfcl_200=<cap>"`` ->
    ``{row task: cap}`` sorted by task. Refuses an unknown task (only
    :data:`LADDER_ROW_TASKS`), a non-positive or non-integer cap, a repeated
    task, or a malformed pair. ``""`` -> ``{}``."""
    out: Dict[str, int] = {}
    for raw in (p for p in str(spec or "").split(",") if p.strip()):
        task, sep, cap = raw.strip().partition("=")
        if not sep or not task or not cap:
            raise ValueError(f"{FLAG_CAP_OVERRIDE}: {raw!r} is not <row_task>=<cap>")
        if task not in LADDER_ROW_TASKS:
            raise ValueError(f"{FLAG_CAP_OVERRIDE}: {task!r} is not a ladder row task {list(LADDER_ROW_TASKS)}")
        if task in out:
            raise ValueError(f"{FLAG_CAP_OVERRIDE}: {task!r} named twice")
        try:
            value = int(cap)
        except ValueError:
            raise ValueError(f"{FLAG_CAP_OVERRIDE}: cap {cap!r} for {task!r} is not an int") from None
        if value <= 0:
            raise ValueError(f"{FLAG_CAP_OVERRIDE}: cap {value} for {task!r} is not positive")
        out[task] = value
    return {k: out[k] for k in sorted(out)}


def format_cap_overrides(caps: Mapping[str, int]) -> str:
    """The inverse of :func:`parse_cap_overrides`, sorted by task."""
    return ",".join(f"{t}={int(caps[t])}" for t in sorted(caps))


def ladder_log_ids(task: str, ids: Sequence[str]) -> List[str]:
    """A ladder selection's ids in the task's LOG vocabulary (what the rows and
    the outcome records carry): ``"BigCodeBench/17"`` -> ``"17"`` for
    BigCodeBench-200 (:func:`bcb_log_id`), the gorilla record id itself for
    BFCL-200. Refuses a task outside :data:`LADDER_ROW_TASKS` or an id in a
    foreign vocabulary."""
    if task not in LADDER_ROW_TASKS:
        raise ValueError(f"ladder_log_ids: {task!r} is not a ladder row task {list(LADDER_ROW_TASKS)}")
    if task == inspect_task("bigcodebench_200"):
        return [bcb_log_id(i) for i in ids]
    return [str(i) for i in ids]


#: The driver's ``--item-selection-json`` value: ``{row task: {ids, n,
#: ids_sha256}}`` — the selection's ids in the PINNED vocabulary, the count and
#: the digest the identity hashes, exactly these three keys per task.
ITEM_SELECTION_JSON_FIELDS: Tuple[str, ...] = ("ids", "n", "ids_sha256")


def format_item_selection_json(selection_by_task: Mapping[str, Sequence[str]]) -> str:
    """The compact ``--item-selection-json`` argument for a ``{task: pinned
    ids}`` selection (validated through :func:`item_selection_identity`)."""
    ident = item_selection_identity(selection_by_task)
    doc = {t: {"ids": [str(i) for i in selection_by_task[t]], "n": ident[t]["n"],
               "ids_sha256": ident[t]["ids_sha256"]} for t in sorted(selection_by_task)}
    return json.dumps(doc, separators=(",", ":"), sort_keys=True)


def parse_item_selection_json(text: str) -> Dict[str, Dict[str, object]]:
    """The inverse of :func:`format_item_selection_json`, VERIFIED: a
    ``{row task: {ids, n, ids_sha256}}`` object (exact keys per task), every task
    a ladder row task, ids a non-empty list of distinct strings in the task's
    pinned vocabulary, ``n == len(ids)`` and ``ids_sha256 == ids_sha256(ids)``.
    Refuses (``ValueError``) otherwise — a selection that does not recompute is
    never generated on."""
    try:
        doc = json.loads(text)
    except ValueError as e:
        raise ValueError(f"{FLAG_ITEM_SELECTION_JSON}: not JSON ({e})") from None
    if not isinstance(doc, Mapping) or not doc:
        raise ValueError(f"{FLAG_ITEM_SELECTION_JSON}: must be a non-empty object of row tasks")
    out: Dict[str, Dict[str, object]] = {}
    for task in sorted(doc):
        block = doc[task]
        if task not in LADDER_ROW_TASKS:
            raise ValueError(f"{FLAG_ITEM_SELECTION_JSON}: {task!r} is not a ladder row task {list(LADDER_ROW_TASKS)}")
        if not isinstance(block, Mapping) or set(block) != set(ITEM_SELECTION_JSON_FIELDS):
            raise ValueError(f"{FLAG_ITEM_SELECTION_JSON}: {task!r} must carry exactly {list(ITEM_SELECTION_JSON_FIELDS)}")
        ids = block["ids"]
        if (not isinstance(ids, list) or not ids or not all(isinstance(i, str) for i in ids)
                or len(set(ids)) != len(ids)):
            raise ValueError(f"{FLAG_ITEM_SELECTION_JSON}: {task!r}.ids must be a non-empty list of distinct strings")
        if block["n"] != len(ids) or isinstance(block["n"], bool):
            raise ValueError(f"{FLAG_ITEM_SELECTION_JSON}: {task!r}.n {block['n']!r} != len(ids) {len(ids)}")
        if block["ids_sha256"] != ids_sha256(ids):
            raise ValueError(f"{FLAG_ITEM_SELECTION_JSON}: {task!r}.ids_sha256 does not recompute over ids")
        ladder_log_ids(task, ids)                        # the pinned vocabulary, or refuse
        out[task] = {"ids": list(ids), "n": len(ids), "ids_sha256": block["ids_sha256"]}
    return out


def item_selection_identity(selection_by_task: Mapping[str, Sequence[str]]) -> Dict[str, Dict[str, object]]:
    """The HASHED value of :data:`IDENTITY_KEY_ITEM_SELECTION`: ``{row task: {n,
    ids_sha256}}`` over the selected ids IN THE GIVEN ORDER (the pin order the
    plan enforces), sorted by task. Refuses an empty selection, a duplicate id
    or a task outside :data:`LADDER_ROW_TASKS`."""
    out: Dict[str, Dict[str, object]] = {}
    for task in sorted(selection_by_task):
        ids = [str(i) for i in selection_by_task[task]]
        if task not in LADDER_ROW_TASKS:
            raise ValueError(f"item_selection: {task!r} is not a ladder row task {list(LADDER_ROW_TASKS)}")
        if not ids:
            raise ValueError(f"item_selection: {task!r} selects no items")
        if len(set(ids)) != len(ids):
            raise ValueError(f"item_selection: {task!r} selects an id twice")
        out[task] = {"n": len(ids), "ids_sha256": ids_sha256(ids)}
    return out


# --------------------------------------------------------------------------- #
# launcher argv (scripts/modal/tinycap_served.py)                              #
# --------------------------------------------------------------------------- #

