CELL_PROMPTED_SAFETY = "prompted__safety_refusal"
CELL_PSRKL_SAFETY = "safety_refusal__psr_kl_all"
TEST_CELLS: Tuple[str, ...] = (CELL_PROMPTED_SAFETY, CELL_PSRKL_SAFETY)
