def source_checkout_root() -> Optional[Path]:
    """The repo root when this module is imported from a SOURCE CHECKOUT (``<root>/src/sisteer/capeval/tinycap/
    contracts.py`` beside ``<root>/configs/``), else None — inside the Modal serving image the package is mounted at
    ``/root/sisteer`` with no ``configs/`` beside it, so a ``__file__``-relative lookup there would
    name a path no tree owns. Callers with a staged tree pass it; callers without one get a loud refusal."""
    here = Path(__file__).resolve()
    if len(here.parents) < 5:
        return None
    root = here.parents[4]
    try:
        if (root / "configs").is_dir() and (root / "src" / "sisteer" / "capeval" / "tinycap" / "contracts.py").samefile(here):
            return root
    except OSError:
        return None
    return None


def tool_parser_live_record_path(rec: Mapping[str, Any], tree: Optional[str | Path] = None) -> Optional[Path]:
    """The checked-in verdict a live record names, resolved against ``tree`` — the STAGED tree for the launch sha
    inside a container, the source checkout on the grading host (:func:`source_checkout_root`) when ``tree`` is None; None
    when neither is at hand (a repo-relative path under :data:`TOOL_PARSER_LIVE_RECORD_DIR`; an absolute path or one
    outside the dir is refused by the gate). ONE source of truth: the tree that pins the roster and the row configs
    also proves the live PASS — never a copy shipped in the image, which would be whatever the LOCAL checkout held
    at build time rather than the sha's tree."""
    root = Path(tree) if tree is not None else source_checkout_root()
    return None if root is None else root / str(rec.get("record") or "")


def tool_parser_live_gate_problem(family: str, *, tree: Optional[str | Path] = None) -> Optional[str]:
    """Why a ``bfcl_200`` / ``bfcl_full`` leg may NOT be planned for ``family`` (None = may): a probe family whose LIVE parser-probe
    PASS record is absent from :data:`TOOL_PARSER_LIVE_PASS`, malformed, or whose checked-in verdict does not PROVE
    it: the record's ``record`` must be a repo-relative path under :data:`TOOL_PARSER_LIVE_RECORD_DIR`
    that exists ON ``tree`` (the staged tree for the launch sha; the source checkout when None — never the
    module's own ``__file__`` inside the image), parses, names this ``family`` and the probe row's model_key, carries
    a ``sha`` the record's ``sha7`` starts with (the staged tree the live half PASSED at), and reads
    ``verdict == "PASS"`` with BOTH halves ``status OK`` + ``verdict PASS`` (the probe's ``_combine`` shape).
    Families outside :data:`TOOL_PARSER_PROBE_FAMILIES` are gated by their manifest alone, as before."""
    if family not in TOOL_PARSER_PROBE_FAMILIES:
        return None
    return _tool_parser_live_record_problem(
        f"family {family!r}", TOOL_PARSER_LIVE_PASS.get(family), tree,
        table="TOOL_PARSER_LIVE_PASS", table_key=family, family=family, want_model_key=TOOL_PARSER_PROBE_MODEL_KEY.get(family),
        record_stem=family,
        absent=(f"family {family!r}: the S5 tool-parser probe's LIVE half has not PASSED — contracts.TOOL_PARSER_LIVE_PASS[{family!r}] is None. "
                "The table pin + manifest admit planning only once the live raw-token replay passes: run "
                "`TINYCAP_APP_NAME=tinycap-bcbw-parser-<family>-<sha7> modal run --detach scripts/modal/tinycap_parser_probe.py --sha <staged sha> "
                f"--family {family}`, pull /vol/tinycap/parser_probe/<model_key>/<sha7>/verdict.json (verdict PASS) INTO the repo as "
                f"{TOOL_PARSER_LIVE_RECORD_DIR}/{family}_verdict_<sha7>.json, and file {{sha7, record, passed_at}} in TOOL_PARSER_LIVE_PASS in the "
                "same change that flips the roster legs"))


def _tool_parser_live_record_problem(who: str, rec: object, tree: Optional[str | Path], *, table: str, table_key: str, family: str,
                                     want_model_key: Optional[str], record_stem: str, absent: str) -> Optional[str]:
    """The ONE proof a live PASS record must give: shape, a commit-prefix sha7, a
    repo-relative checked-in path named ``<record_stem>_verdict_<sha7>.json`` under the record dir and present ON ``tree``, parsing,
    the verdict's family / model_key / sha / PASS with BOTH halves OK + PASS."""
    if rec is None:
        return absent
    if not isinstance(rec, Mapping) or set(rec) != set(TOOL_PARSER_LIVE_RECORD_FIELDS) or not all(str(rec.get(k) or "").strip() for k in TOOL_PARSER_LIVE_RECORD_FIELDS):
        return f"{who}: {table} record {rec!r} is not {{{', '.join(TOOL_PARSER_LIVE_RECORD_FIELDS)}}} with every field non-empty"
    sha7 = str(rec["sha7"])
    if not re.fullmatch(r"[0-9a-f]{7,40}", sha7):
        return f"{who}: {table} sha7 {sha7!r} is not a commit prefix"
    rel = str(rec["record"])
    if Path(rel).is_absolute() or not rel.startswith(TOOL_PARSER_LIVE_RECORD_DIR + "/"):
        return (f"{who}: {table} record {rel!r} is not a repo-relative path under {TOOL_PARSER_LIVE_RECORD_DIR}/ — the "
                "verdict is CHECKED IN as a pinned artifact, never referenced by an outside path")
    path = tool_parser_live_record_path(rec, tree)
    if path is None:
        return (f"{who}: no tree to read the live verdict {rel} from — contracts is not imported from a source checkout "
                f"(module at {Path(__file__).resolve()}; the Modal image mounts it at /root/sisteer with no configs/ beside it) and the "
                "caller passed no staged tree; pass tree=<the staged tree for the launch sha> (the same root the roster and row configs are read from)")
    if not path.is_file():
        return f"{who}: the live verdict {rel} named by {table} is not on tree {path.parents[len(Path(rel).parts) - 1]} — a path string is not proof"
    if Path(rel).name != f"{record_stem}_verdict_{sha7}.json":
        return f"{who}: {table} record {rel!r} is not named {record_stem}_verdict_{sha7}.json — the file name binds the record to its key and sha"
    try:
        doc = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        return f"{who}: the live verdict {rel} does not parse ({e})"
    if not isinstance(doc, Mapping):
        return f"{who}: the live verdict {rel} is not an object"
    if doc.get("family") != family:
        return f"{who}: the live verdict {rel} is for family {doc.get('family')!r}"
    if doc.get("model_key") != want_model_key:
        return f"{who}: the live verdict {rel} names model_key {doc.get('model_key')!r}, not {want_model_key!r}"
    doc_sha = str(doc.get("sha") or "")
    if not doc_sha or not (sha7.startswith(doc_sha) or doc_sha.startswith(sha7)):
        return f"{who}: the live verdict {rel} is for staged sha {doc_sha!r}, not the record's {sha7!r}"
    if doc.get("verdict") != "PASS":
        return f"{who}: the live verdict {rel} reads {doc.get('verdict')!r}, not PASS"
    for half in ("offline", "live"):
        blk = doc.get(half)
        if not isinstance(blk, Mapping) or blk.get("status") != "OK" or not isinstance(blk.get("verdict"), Mapping) or blk["verdict"].get("verdict") != "PASS":
            return f"{who}: the live verdict {rel}'s {half} half is not (status OK, verdict PASS): {blk!r}"
    return None


