class IfevalPromptClassUnmeasured(ValueError):
    """A prompted IFEval cell whose SI has no measured prompt class / geometry entry."""


def ifeval_prompt_class_of_cell(cell: str) -> str:
    """The IFEval PROMPT CLASS of a cell: ``short`` for ``none``, every object
    cell (no system turn) and the safety_refusal SI; ``long_si`` for the
    constitution SI; any other prompted SI refuses by name — its window was
    never measured (:class:`IfevalPromptClassUnmeasured`)."""
    parsed = parse_launcher_cell(cell)
    if parsed.kind != "prompted":
        return IFEVAL_PROMPT_CLASS_SHORT
    cls = IFEVAL_PROMPT_CLASS_OF_SI.get(str(parsed.si))
    if cls is None:
        raise IfevalPromptClassUnmeasured(
            f"prompted IFEval cell {cell!r}: SI {parsed.si!r} has no measured IFEval prompt class "
            f"({dict(IFEVAL_PROMPT_CLASS_OF_SI)}) — measure it (scripts/sdfbase/ifeval/measure_ifeval_geometry.py) "
            "and register its entries before launching it against IFEval")
    return cls


def ifeval_geometry_entry(cell: str, cap: int) -> str:
    """The registered geometry entry an IFEval configuration of ``cell`` at
    ``cap`` resolves: the cap's entry of the cell's prompt class."""
    if int(cap) not in IFEVAL_CAP_LADDER:
        raise ValueError(f"cap {cap!r} is not a rung of the IFEval ladder {list(IFEVAL_CAP_LADDER)}")
    return IFEVAL_GEOMETRY_ENTRY_BY_CLASS[ifeval_prompt_class_of_cell(cell)][int(cap)]


#: the matrix row statuses: ``launch`` (a pass-1 row), ``held`` (a HARD exclusion,
#: P41), and — the follow-up — ``deferred``: a DESIGN SLOT (AlphaSteer / Arditi
#: refusal at minimal over-refusal strength, one per model) whose object sha is
#: filled later from a per-model ``(object_sha256, view, rung, selection_rule)``
#: record; excluded from the launch set, and the dispatcher refuses to launch it
IFEVAL_STATUS_LAUNCH, IFEVAL_STATUS_HELD, IFEVAL_STATUS_DEFERRED = "launch", "held", "deferred"
IFEVAL_ROW_STATUSES: Tuple[str, ...] = (IFEVAL_STATUS_LAUNCH, IFEVAL_STATUS_HELD, IFEVAL_STATUS_DEFERRED)
#: the frozen matrix (``make_ifeval_matrix.py``'s output; ``ifeval_contracts.IFEVAL_MATRIX_REL`` reads this
#: spelling) — the ONE document whose row statuses the dispatcher, the launcher's planner and the container read
IFEVAL_MATRIX_REL = "configs/sdfbase/ifeval/matrix.json"
#: EVERY IFEval matrix document the planner's and the container's hold check read (a document nobody registers
#: is a hold nobody enforces, as the GSM8K registration showed) — the frozen 40-row matrix AND the sibling
#: ``qwen_seedrep`` document (30 rows: the six roster views, native serving). A registered document MUST exist
#: on the tree (:func:`load_ifeval_matrices` refuses a missing one by name); a (slug, cell) is keyed once
#: ACROSS the documents (their slug sets are disjoint by construction).
IFEVAL_MATRIX_QWEN_SEEDREP_REL = "configs/sdfbase/ifeval/matrix_qwen_seedrep.json"
IFEVAL_MATRIX_DOCUMENTS: Tuple[str, ...] = (IFEVAL_MATRIX_REL, IFEVAL_MATRIX_QWEN_SEEDREP_REL)
#: the REC a container files for a configuration whose matrix row is HELD or DEFERRED — a refusal the
#: dispatcher never retries on GPU (:data:`REFUSAL_REC_NAMES`); the hold is the matrix's, not the command line's
REC_IFEVAL_ROW_HELD = "IFEVAL_ROW_HELD"


class IfevalMatrixUnreadable(ValueError):
    """The frozen IFEval matrix an IFEval configuration must be checked against cannot be read from the tree."""


def _load_ifeval_document(path: Path, *, what: str) -> Dict[str, object]:
    """ONE registered IFEval matrix document at ``path`` (``what`` names it in the refusal: the frozen matrix, a registered
    sibling). Refuses by name when absent or malformed — an IFEval configuration is never planned or served without the
    document that says whether its row is launchable."""
    try:
        doc = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        raise IfevalMatrixUnreadable(
            f"{what} {path} cannot be read ({type(e).__name__}: {str(e)[:120]}) — an IFEval configuration is planned and "
            f"served only against every registered document (IFEVAL_MATRIX_DOCUMENTS: {list(IFEVAL_MATRIX_DOCUMENTS)})") from None
    if not isinstance(doc, Mapping) or not isinstance(doc.get("rows"), list) or not doc["rows"]:
        raise IfevalMatrixUnreadable(f"{path}: not an IFEval matrix (no rows)")
    return dict(doc)


def _ifeval_document_what(rel: str) -> str:
    return "the frozen IFEval matrix" if rel == IFEVAL_MATRIX_REL else "the registered IFEval matrix document"


def load_ifeval_matrix(tree: "str | Path") -> Dict[str, object]:
    """The frozen matrix (:data:`IFEVAL_MATRIX_REL`) read off ``tree`` — the launcher's local checkout at plan time,
    the STAGED tree in the container (:func:`_load_ifeval_document`)."""
    return _load_ifeval_document(Path(str(tree)) / IFEVAL_MATRIX_REL, what=_ifeval_document_what(IFEVAL_MATRIX_REL))


def load_ifeval_matrices(tree: "str | Path", documents: Sequence[str] = IFEVAL_MATRIX_DOCUMENTS) -> Dict[str, object]:
    """EVERY registered IFEval matrix document (:data:`IFEVAL_MATRIX_DOCUMENTS`) read off ``tree`` and MERGED into
    one ``{"rows": [...], "documents": [...]}`` view for :func:`ifeval_hold_problem` / :func:`ifeval_matrix_row_status`
    — the planner's and the container's hold check read THIS, so the sibling ``qwen_seedrep`` document's statuses are
    enforced exactly like the frozen matrix's. A registered document that is absent or
    malformed refuses by name through :func:`load_ifeval_matrix` (never admitted around a missing document); a
    (slug, cell) carried by two documents refuses (the documents' slug sets are disjoint by construction)."""
    rows: List[Dict[str, object]] = []
    seen: Dict[Tuple[str, str], str] = {}
    for rel in documents:
        doc = _load_ifeval_document(Path(str(tree)) / rel, what=_ifeval_document_what(rel))
        for r in doc["rows"]:
            if isinstance(r, Mapping):
                key = (str(r.get("slug")), str(r.get("cell")))
                if key in seen and seen[key] != rel:
                    raise ValueError(f"IFEval matrix documents {seen[key]} and {rel} both carry a row for {key} — "
                                     "a (slug, cell) is keyed once across the registered documents")
                seen[key] = rel
                rows.append(dict(r))
    return {"rows": rows, "documents": list(documents)}


def ifeval_matrix_row_status(matrix: Mapping[str, object], *, slug: str, cell: str
                             ) -> Tuple[Optional[str], Optional[str]]:
    """``(status, reason)`` of the frozen matrix's row for ``(slug, cell)`` — exactly the fields the dispatcher's
    ``select_rows`` reads (``status``; ``held_reason`` for a held row, the ``deferred.record`` for a design slot) —
    or ``(None, None)`` when the matrix has no such row (the matrix does not speak to it). Two rows for one
    ``(slug, cell)`` refuse: the matrix keys a cell once per slug."""
    rows = [r for r in matrix.get("rows", []) if isinstance(r, Mapping)
            and str(r.get("slug")) == str(slug) and str(r.get("cell")) == str(cell)]
    if not rows:
        return None, None
    if len(rows) > 1:
        raise ValueError(f"the IFEval matrix carries {len(rows)} rows for {slug} x {cell} — a cell is keyed once per slug")
    (row,) = rows
    status = row.get("status")
    if status == IFEVAL_STATUS_HELD:
        return IFEVAL_STATUS_HELD, str(row.get("held_reason") or "no held_reason recorded")
    if status == IFEVAL_STATUS_DEFERRED:
        rec = (row.get("deferred") or {}).get("record") if isinstance(row.get("deferred"), Mapping) else None
        return IFEVAL_STATUS_DEFERRED, f"a design slot with no object sha; filled from {rec}"
    return (str(status) if status is not None else None), None


def ifeval_hold_problem(matrix: Mapping[str, object], *, slug: str, cell: str) -> Optional[str]:
    """Why an IFEval configuration of ``(slug, cell)`` may NOT be planned or served under the frozen matrix's policy:
    its row is HELD (P41 — a hard exclusion until the refit lands), DEFERRED (a design slot whose object sha
    is not filled), or carries a status outside :data:`IFEVAL_ROW_STATUSES`; ``None`` for a launch row and for a
    cell the matrix has no row for (the shakedown's probe cell is not a matrix row). The dispatcher's ``select_rows``
    reads the same statuses; this is the same policy at the launcher's direct ``--cells … --pass1`` path and at the
    container, where a hand-typed cell selection used to plan and spawn a held row."""
    status, reason = ifeval_matrix_row_status(matrix, slug=slug, cell=cell)
    if status == IFEVAL_STATUS_HELD:
        return (f"{slug} x {cell}: the frozen IFEval matrix holds this row HELD ({reason}) — a hard exclusion (P41); the "
                "matrix, not the command line, decides what launches; nothing is planned or served for it")
    if status == IFEVAL_STATUS_DEFERRED:
        return (f"{slug} x {cell}: the frozen IFEval matrix holds this row DEFERRED ({reason}) — never launched until the "
                "record is filled and the matrix regenerated")
    if status is not None and status not in IFEVAL_ROW_STATUSES:
        return f"{slug} x {cell}: the frozen IFEval matrix records status {status!r}, not one of {list(IFEVAL_ROW_STATUSES)}"
    return None
#: the IFEval dispatcher's state file (``scripts/tinycap_ifeval_dispatch.py``:
#: rewritten atomically after every transition under the local wave root), the
#: ONE spelling the dispatcher and its tests read
IFEVAL_DISPATCH_STATE = "dispatch_state.json"
#: the names the matrix / analysis lane's ``ifeval_contracts`` reads under
