IFEVAL_TASK = inspect_task(IFEVAL_TASK_NAME)
IFEVAL_DATASET_PATH = "google/IFEval"
PRIMARY_SCORER_IFEVAL = "instruction_following"
PRIMARY_VALUE_KEY_IFEVAL = "prompt_level_strict"
LANGDETECT_SEED = IFEVAL_LANGDETECT_SEED
IFEVAL_OUTCOME_ITEM_FIELDS = TASK_OUTCOME_ITEM_FIELDS_IFEVAL
IFEVAL_OUTCOME_ITEM_FIELDS_NO_SWITCH = TASK_OUTCOME_ITEM_FIELDS_IFEVAL_NO_SWITCH


def ifeval_tag(model_key: str, view: str) -> str:
    """The TAG (the GSM8K house rule): the bare key for ``main``,
    ``<key>_<view>`` otherwise — the path component the matrix path's
    ``ifeval_paths`` and the overlay configs are named by. Admits :data:`IFEVAL_VIEWS`
    — the two instrument views and the six batch-64 seed views
    (``qwen35_4b_s1``); any other view refuses by name."""
    if view not in IFEVAL_VIEWS:
        raise ValueError(f"view {view!r} is not one of {list(IFEVAL_VIEWS)}")
    return model_key if view == BANK_VIEW_MAIN else f"{model_key}_{view}"


#: the per-TAG overlay config / harness manifest the launcher's ``--config``
#: names (written by ``make_ifeval_overlays.py``)
IFEVAL_OVERLAY_CONFIG_REL = "configs/sdfbase/ifeval/sdfbase_full22_{tag}.ifeval.yaml"
IFEVAL_OVERLAY_MANIFEST_REL = "configs/capeval/manifests/petri_full22_{tag}.ifeval.yaml"


def ifeval_config_path(model_key: str, view: str) -> str:
    return IFEVAL_OVERLAY_CONFIG_REL.format(tag=ifeval_tag(model_key, view))


def ifeval_objects_dir(model_key: str, view: str) -> str:
    """The bank VIEW on the volume a slug's ``objects_dir`` points at: the STAGED
    full22 bank ``/vol/objects/sdfbase/full22/<key>/<view>`` (:func:`full22_objects_dir`)
    — the directory every bank's ``staged_manifest.json`` names as its ``objects_dir``,
    a dereferenced copy of the cluster's ``cells_view/<view>`` verified against the
    roster pins. The plan's spelling ``/vol/objects/sdfbase/<key>/cells_view/<view>``
    (§8.1 / Appendix B) was never staged: the wave shakedown (2026-09-13) found no such
    directory on the volume, so every fitted-cell preflight (``config_and_objects_present``)
    and every lens standup (``--defenses-dir``) would have refused by path — the row names
    the bank that exists. The IFEval rows are still NOT full22 rows (:func:`is_full22_row`
    excludes them by slug), so the bcb-bfcl-200-widen gates do not fire on them. The six
    seed views serve from the same root — ``/vol/objects/sdfbase/full22/qwen35_4b/s1``
    — staged ONCE by ``stage_seed_banks_modal.sh`` (bare cell ids; the Arditi
    ``arditi_allpos`` object as an extra bare-cell dir inside each ``s<s>`` view)."""
    if view not in IFEVAL_VIEWS:
        raise ValueError(f"view {view!r} is not one of {list(IFEVAL_VIEWS)}")
    return full22_objects_dir(model_key, view)


#: the fit BASE the sdf-base objects of each model were transferred FROM (read
#: 2026-09-12 off the staged banks' ``train_budget_meta.json`` on the cluster):
#: gemma and Qwen were fit on their base checkpoints and are served on the
#: instruct target; Nemotron was fit on the SERVED model itself (no transfer —
#: None, the field's meaning); Llama's base fits are a transfer too but the
#: base id is recorded in the staged object's sidecar and is NOT typed here
#: unverified (None; the derived-object provenance preflight reads the sidecar).
_IFEVAL_BASE_HF: Mapping[str, Optional[str]] = {
    "gemma4e4b": "google/gemma-4-E4B", "qwen35_4b": "Qwen/Qwen3.5-4B-Base",
    "nemotron3nano4b": None, "llama8b": None}


def is_ifeval_row(row: ModelRow) -> bool:
    """Whether a registry row is one of the IFEval wave's seven slugs — the gate
    the launcher applies its ported full22 standup composition (the text-only
    pin, the Nemotron contract) and post-standup attestation refusals to; a
    legacy two-SI row's launcher behaviour stays what it was."""
    return str(getattr(row, "slug", "")) in set(IFEVAL_SLUGS.values())


def _ifeval_row(model_key: str, view: str) -> ModelRow:
    """One IFEval slug row (P27), written narrowly in the dropped battery's shape:
    the pinned target, the per-TAG overlay config, the (model, view) bank view on
    the volume, the SERVING family, thinking OFF only, the family's verified
    tool-parser manifest where one exists (gemma, llama; qwen3_5 since the
    batch-64 capability-agentic queue landed — the full22 qwen35_4b
    manifest, the same target + pin as IFEVAL_MODEL_PINS["qwen35_4b"]; nemotron_h
    since its own live PASS at 8365992, 2026-09-23 — the full22 nemotron
    manifest), the fit base where the objects were transferred."""
    hf, rev = IFEVAL_MODEL_PINS[model_key]
    # nemotron_h joined 2026-09-23: the S5 live probe PASSED on the staged tree 8365992 (TOOL_PARSER_LIVE_PASS), qwen3_xml pinned
    manifest = {"gemma4": PETRI_MANIFEST_GEMMA4E4B, "llama": PETRI_MANIFEST_TWOSI,
                "qwen3_5": PETRI_MANIFEST_FULL22_QWEN35_4B,
                "nemotron_h": PETRI_MANIFEST_FULL22_NEMOTRON3NANO4B}.get(FAMILY_BY_MODEL_KEY[model_key])
    return ModelRow(slug=IFEVAL_SLUGS[(model_key, view)], hf=hf, rev=rev,
                    cfg=ifeval_config_path(model_key, view),
                    objects_dir=ifeval_objects_dir(model_key, view),
                    model_key=model_key, family=FAMILY_BY_MODEL_KEY[model_key],
                    thinking_modes=(THINKING_OFF,), petri_manifest=manifest,
                    base_hf=_IFEVAL_BASE_HF[model_key])


#: b64-capability-agentic-queue (2026-09-23): the per-family constants of the ALL-MODELS ONE-SEED rows — the served
#: pin, the serving family, the tool-parser manifest and the fit base, each the family's EXISTING lane row's
#: (`gemma4e4b-f22`, `llama8b-f22`, `nemotron3nano4b`), spelled once. nemotron_h's manifest is None until the S5 live
#: probe PASSES (the same gate as its `main` row: PETRI_MANIFEST_FULL22_NEMOTRON3NANO4B lands with the PASS record).
_BCBW_ALLMODELS_ROW_KW: Mapping[str, Mapping[str, object]] = {
    "gemma4e4b": dict(hf=_GEMMA4E4B["hf"], rev=_GEMMA4E4B["rev"], family="gemma4",
                      petri_manifest=PETRI_MANIFEST_GEMMA4E4B, base_hf="google/gemma-4-E4B"),
    "llama8b": dict(hf=_LLAMA8B["hf"], rev=_LLAMA8B["rev"], family="llama",
                    petri_manifest=PETRI_MANIFEST_TWOSI, base_hf="NousResearch/Meta-Llama-3.1-8B"),
    "nemotron3nano4b": dict(hf="nvidia/NVIDIA-Nemotron-3-Nano-4B-BF16", rev="dfaf35de3e30f1867dd8dbc38a7fc9fb52d3914f",
                            family="nemotron_h", petri_manifest=PETRI_MANIFEST_FULL22_NEMOTRON3NANO4B, base_hf=None),   # the S5 live PASS at 8365992
}


def _bcbw_allmodels_row(model_key: str, view: str) -> ModelRow:
    """One all-models one-seed lane row (``<model_key>-f22s1`` / ``-f22s1p``): the family's served pin over the staged
    bank ``/vol/objects/sdfbase/full22/<model_key>/<view>``, the generated explicit-cells config of the (model key,
    view), thinking OFF; the slug from :data:`BCBW_SLUG_OF`, never re-spelled."""
    kw = dict(_BCBW_ALLMODELS_ROW_KW[model_key])
    return _row(BCBW_SLUG_OF[(model_key, view)], cfg=bcbw_config_path(model_key, view),
                objects_dir=full22_objects_dir(model_key, view), model_key=model_key,
                thinking_modes=(THINKING_OFF,), **kw)




