M5T_EXT_CELLS: Tuple[str, ...] = ("constv2-mix-full__lora_r4_ce", "constv2ctl2-full__lora_r4_ce")
#: the models the extension runs on (the spec's four minus llama8b, whose rows are E2's; glm is the appendix model
#: and gets no extension row — plan P9 / Q1)
M5T_EXT_MODELS: Tuple[str, ...] = ("gemma4e4b", "qwen35_4b", "nemotron3nano4b")
