#: ``prompt_opens_think_on`` — certified against the live header AND the
#: attested ``thinking_header.on_ids`` / ``off_ids`` (5 / 7, §2.5.7) by the
#: driver (S3.4) before any generation.
QWEN35_HEADER_IDS_OFF: Tuple[int, ...] = (248045, 74455, 198, 248068, 271, 248069, 271)
QWEN35_HEADER_IDS_ON: Tuple[int, ...] = (248045, 74455, 198, 248068, 198)
QWEN35_THINK_OPEN_ID = 248068
QWEN35_THINK_CLOSE_ID = 248069


def _reconciled(*names: str) -> None:
    """Refuse — naming the constant — should any of ``names`` read ``None`` at
    CALL time. Every one of :data:`OOS_CONTRACT_PLACEHOLDERS` is filled from
    the FINAL contract, so this guards a MUTATED module (a test un-filling a
    constant, a bad edit), never a pending reconciliation; read off the module
    at call time so a monkeypatch is what every consumer sees."""
    unset = [n for n in names if globals()[n] is None]
    if unset:
        raise OutOfSupportDeclarationUnreconciled(
            f"the lens-half contract name(s) {unset} read None: step B0 filled every constant in "
            "contracts.OOS_CONTRACT_PLACEHOLDERS from the FINAL contract (contract-2.5.md), so a "
            "None here is a mutated module — refusing to proceed on a missing name")


def oos_declaration_ready() -> bool:
    """True iff every REQUEST-side constant (:data:`OOS_REQUEST_PLACEHOLDERS`)
    is filled — True on the shipped module; the provider and the bites
    probe REFUSE to send a thinking-ON lens-route request while this is False
    (a mutated module). The contract's own pre-landing behaviour is the second
    fail-closed layer: an un-landed proxy forwards the key, the locator
    refuses, the probe FAILS (§2.5.8)."""
    return all(globals()[n] is not None for n in OOS_REQUEST_PLACEHOLDERS)


def thinking_on_declaration(*, lens: bool, arm: str, header_located: bool = True) -> Dict[str, bool]:
    """The ONE predicate every tinycap request builder applies (CONTRACT
    §2.5.4, narrowed 2026-09-09): the body fragment
    ``{"petri_thinking_on": true}`` iff the request sends ``enable_thinking:
    true`` on a LENS route whose served mask is HEADER-LOCATED
    (``header_located``: some served op's positions in
    :data:`HEADER_LOCATED_MODES`) — the declaration exists to stop a render
    change from silently mis-masking a header-anchored mask, and an
    all-position / last-row cell has no such mask, so NO declaration is sent
    there (the proxy accepts the undeclared ON render when its
    ``lens_served_positions`` fact says so, and refuses a declaration on such a
    cell as vacuous) — and ``{}`` otherwise: never on an OFF arm, never on the
    base route (400 ``thinking_on_not_lens``, §2.5.5), never alone
    (``thinking_on_mismatch``, §2.5.6). ``header_located`` defaults True (the
    parent's ``positions: response`` cell; every pre-existing caller
    byte-identical). Presence semantics (§2.5.12): the key is emitted with the
    boolean ``true`` or NOT AT ALL — never ``false`` ("not a declaration": ON
    kwargs beside it refuse ``thinking_on_undeclared``), never ``null``
    (``thinking_on_invalid`` on every route); and :func:`chat_template_kwargs`
    always carries the boolean, never ``null`` (``thinking_kwargs_invalid`` on
    every route, ``/v1/tokenize`` included). ``arm`` is a WHOLE arm
    (:data:`THINKING_MODES`); ``per-task`` refuses. Refuses (fail closed)
    should either request-side constant read ``None``."""
    on = enable_thinking(arm)
    if not (lens and on and header_located):
        return {}
    _reconciled(*OOS_REQUEST_PLACEHOLDERS)
    return {OOS_THINKING_DECLARATION_KEY: OOS_THINKING_DECLARATION_VALUE}


def thinking_mode(on: bool) -> str:
    """The whole-arm token for a boolean ``enable_thinking``: :data:`THINKING_ON`
    or :data:`THINKING_OFF`."""
    return THINKING_ON if on else THINKING_OFF


def render_fragment(*, lens: bool, arm: str, header_located: bool = True) -> Dict[str, object]:
    """The two body fragments every tinycap request carries for its render,
    together: the arm's :func:`chat_template_kwargs` and — on a HEADER-LOCATED
    lens route under ON — the :func:`thinking_on_declaration` beside it (``{}``
    otherwise; ``header_located`` defaults True, the pre-existing behaviour)."""
    return {**chat_template_kwargs(arm),
            **thinking_on_declaration(lens=lens, arm=arm, header_located=bool(header_located))}


def is_declared_configuration(cell: str, *, arm: str, out_of_support: bool,
                              header_located: bool = True) -> bool:
    """Whether a configuration's standup wears the DECLARED cell spelling
    (contract §2.5.1 / §2.5.10 Q8 / §2.5.11 Q7(ii)): out of support, the whole
    thinking-ON arm, a LENS cell — AND a HEADER-LOCATED served mask (an
    all-position object served thinking-ON out of support resolves the PLAIN
    route spelling; the lens refuses its declaration as vacuous). The ``none``
    standups and every OFF standup are undeclared —
    ``--cell`` bare. ONE predicate for the launcher's standup argv, its hashed
    expectation, its attestation lookup and its dry run, the analysis's
    expected route vmodel and the fixtures, so no two of them can disagree
    about the spelling a configuration wears. ``header_located`` defaults True
    (every pre-existing caller byte-identical)."""
    return bool(out_of_support) and arm == THINKING_ON and is_lens_cell(cell) and bool(header_located)


def expected_serve_out_of_support(*, lens: bool, arm: str, out_of_support: bool,
                                  header_located: bool = True) -> object:
    """The CONTRACT-DERIVED ``serve_out_of_support`` expectation for one
    configuration — PURE, computable with no server, so the launcher's resume
    decision runs before any standup and the driver hashes it before any store
    is touched: a HEADER-LOCATED lens cell served
    thinking-ON out of support -> :data:`OOS_CELL_DECLARATION_EXPECTED` (a
    JSON-canonical copy; refuses should the constant read ``None``); every
    other configuration (the base route, any OFF arm, any in-support run, an
    UNDECLARED all-position object) -> ``None``, and the
    driver then writes NO ``serve_out_of_support`` key at all (absent, never
    null-present). The hashed identity carries THIS value, never the
    endpoint's attestation, which is compared against it after standup as a
    refusal. ``header_located`` defaults True (pre-existing callers unchanged)."""
    on = enable_thinking(arm)
    if not (lens and out_of_support and on and header_located):
        return None
    _reconciled("OOS_CELL_DECLARATION_EXPECTED")
    return json.loads(json.dumps(OOS_CELL_DECLARATION_EXPECTED, sort_keys=True))


def serve_out_of_support_attested(ep: Mapping[str, object], map_key: str) -> object:
    """The comparable core of an attestation document (``endpoint.json`` or the
    ``/v1/models`` ``petri_proxy`` block) for the harness's OWN cell ``map_key``:
    the sorted token list under :data:`SERVE_OUT_OF_SUPPORT_KEY`, or ``None``
    when the map is absent or does not name the cell. Contract §2.5.1: look up
    your own cell, never validate the whole map — siblings of any shape are
    ignored; the own value must be exactly ``{"serve_out_of_support": [<tokens
    in OUT_OF_SUPPORT_TOKENS>]}`` (non-empty, no duplicates) or it refuses
    (:class:`OutOfSupportAttestationError`), as does a non-null error key.
    Refuses should either key name read ``None``. A compare-site helper,
    never an identity input."""
    _reconciled("PROXY_IDENTITY_SERVE_DECLARATIONS", "PROXY_IDENTITY_SERVE_DECLARATIONS_ERROR")
    if not isinstance(ep, Mapping):
        raise OutOfSupportAttestationError(
            f"attestation document is a {type(ep).__name__}, not a mapping")
    err = ep.get(PROXY_IDENTITY_SERVE_DECLARATIONS_ERROR)
    if err is not None:
        raise OutOfSupportAttestationError(
            f"{PROXY_IDENTITY_SERVE_DECLARATIONS_ERROR}: {err!r} — the workers attested no "
            "serve declarations (or disagreed); nothing to compare, refusing")
    declarations = ep.get(PROXY_IDENTITY_SERVE_DECLARATIONS)
    if declarations is None:
        return None
    if not isinstance(declarations, Mapping):
        raise OutOfSupportAttestationError(
            f"{PROXY_IDENTITY_SERVE_DECLARATIONS} is a {type(declarations).__name__}, not the "
            "per-cell map the contract describes")
    if map_key not in declarations:
        return None
    value = declarations[map_key]
    where = f"{PROXY_IDENTITY_SERVE_DECLARATIONS}[{map_key!r}]"
    if not isinstance(value, Mapping) or set(value) != {SERVE_OUT_OF_SUPPORT_KEY}:
        raise OutOfSupportAttestationError(
            f"{where} = {value!r} is not the closed shape {{{SERVE_OUT_OF_SUPPORT_KEY!r}: "
            f"[<tokens>]}} the harness's own cell wears (a {SERVE_EXPERIMENT_KEY!r} shape "
            "belongs to experiment 2's cells, never to this one)")
    tokens = value[SERVE_OUT_OF_SUPPORT_KEY]
    if not isinstance(tokens, (list, tuple)) or not tokens:
        raise OutOfSupportAttestationError(
            f"{where}.{SERVE_OUT_OF_SUPPORT_KEY} = {tokens!r} is not a non-empty list of render "
            f"tokens from {list(OUT_OF_SUPPORT_TOKENS)}")
    for tok in tokens:
        if not isinstance(tok, str) or tok not in OUT_OF_SUPPORT_TOKENS:
            raise OutOfSupportAttestationError(
                f"{where}.{SERVE_OUT_OF_SUPPORT_KEY} carries {tok!r}, outside the closed "
                f"vocabulary {list(OUT_OF_SUPPORT_TOKENS)}")
    if len(set(tokens)) != len(tokens):
        raise OutOfSupportAttestationError(
            f"{where}.{SERVE_OUT_OF_SUPPORT_KEY} carries a duplicate token: {list(tokens)!r}")
    return sorted(tokens)


def attested_thinking_header(models_payload: Optional[Mapping[str, object]]
                             ) -> Optional[Mapping[str, object]]:
    """The ``thinking_header`` block (``{"switch", "moves", "off_ids", "on_ids"}``)
    at the key path :data:`THINKING_HEADER_SOURCE` of the ``/v1/models`` payload
    — the ONLY source the contract names (§2.5.7) — or ``None`` when absent. A
    non-mapping block refuses (:class:`OutOfSupportAttestationError`); the type
    and length checks are the driver's certification, which also refuses
    §2.5.12's PARTIAL fact (``moves``/``on_ids`` null beside a reason under
    :data:`THINKING_HEADER_ERROR_SOURCE`) by type. Refuses should the path read
    ``None``. Evidence, never hashed."""
    _reconciled("THINKING_HEADER_SOURCE")
    if models_payload is None:
        return None
    if not isinstance(models_payload, Mapping):
        raise OutOfSupportAttestationError(
            f"/v1/models payload is a {type(models_payload).__name__}, not a mapping")
    node: object = models_payload
    for part in THINKING_HEADER_SOURCE:
        if not isinstance(node, Mapping) or part not in node:
            return None
        node = node[part]
    if node is None:
        return None
    if not isinstance(node, Mapping):
        raise OutOfSupportAttestationError(
            f"/v1/models {'.'.join(THINKING_HEADER_SOURCE)} is a {type(node).__name__}, not the "
            "thinking_header mapping the contract describes")
    return dict(node)


def raw_thinking_header(models_payload: Optional[Mapping[str, object]]) -> object:
    """The node at :data:`THINKING_HEADER_SOURCE` of the ``/v1/models`` payload
    VERBATIM — whatever type it has — or ``None`` when the path is absent. The
    certification (:func:`certify_thinking_header`) judges the shape itself and
    writes the COMPLETE evidence block for a non-mapping node (every
    ``OOS_EVIDENCE_*`` key present, typed nulls); :func:`attested_thinking_header`
    is the validating reader for callers that want a mapping or a refusal."""
    _reconciled("THINKING_HEADER_SOURCE")
    if not isinstance(models_payload, Mapping):
        return None
    node: object = models_payload
    for part in THINKING_HEADER_SOURCE:
        if not isinstance(node, Mapping) or part not in node:
            return None
        node = node[part]
    return node


class StampRegimes(NamedTuple):
    """The per-leg stamp TRIPLE in its ONE order — ``(salt_regime,
    resumed_policy, render_regime)``, contract §2.5.11's five rows — under
    the SUMMARY's spellings of the three fields
    (:data:`SUMMARY_PAYLOAD_FIELDS`). Both the reader of a response's stamp
    block (:func:`stamp_regimes`) and the expectation table
    (:func:`expected_stamp_regimes`) return this type, so a consumer compares
    BY NAME (``.salt_regime``, ``._asdict()``) and no zip by position can pair
    a render label with a salt label (the two once disagreed on order). A
    member read off a stamp is ``None`` when the block lacks that field."""

    salt_regime: Optional[str]
    resumed_policy: Optional[str]
    render_regime: Optional[str]


#: The closed vocabulary of each stamp field, by the :class:`StampRegimes`
#: field name — the ONE mapping the extraction (:func:`stamp_regimes`), the
#: provider's per-response check and the analysis read.
STAMP_VOCABULARY: Mapping[str, Tuple[str, ...]] = {
    "salt_regime": SALT_REGIME_LITERALS, "resumed_policy": RESUMED_POLICY_LABELS,
    "render_regime": RENDER_REGIME_LITERALS}
#: stamp field name -> the ``petri`` block key it is read from
STAMP_KEY_OF_FIELD: Mapping[str, str] = {
    "salt_regime": STAMP_KEY_SALT_REGIME, "resumed_policy": STAMP_KEY_RESUMED_POLICY,
    "render_regime": STAMP_KEY_RENDER_REGIME}


def stamp_regimes(completion: Mapping[str, object]) -> StampRegimes:
    """The :class:`StampRegimes` off one completion's ``petri`` stamp block:
    the two code-verified fields and the render
    regime under :data:`STAMP_KEY_RENDER_REGIME` (CONTRACT §2.5.5, stamped on
    every route) — the ONE extraction site the provider, the summary check and
    the bites probe read through, PRESENCE and raw TYPE preserved: a member
    reads ``None`` ONLY when its key — or the whole block —
    is genuinely missing (a pre-landing proxy; the additive rule's "absent",
    judged by the caller against the run's support); a PRESENT value that is
    null, empty, not a string, or outside the field's closed vocabulary
    (:data:`STAMP_VOCABULARY`) refuses here, on EVERY run,
    ``OOS_SALT_POLICY_UNEXPECTED`` naming the key, the value and its type — an
    incompatible proxy is refused, never read as "not stamped". A present
    block that is not a mapping refuses the same way. The CHECK that every
    response of a leg carries one value of each, and the leg's expected triple
    (§2.5.11's five rows), is the driver's (S3)."""
    if not isinstance(completion, Mapping) or STAMP_BLOCK_KEY not in completion:
        return StampRegimes(None, None, None)
    block = completion[STAMP_BLOCK_KEY]
    if not isinstance(block, Mapping):
        raise OutOfSupportAttestationRefusal(
            REC_OOS_SALT_POLICY_UNEXPECTED,
            f"the response's {STAMP_BLOCK_KEY} stamp block is {block!r} ({type(block).__name__}), not "
            "the mapping the proxy stamps — a present malformed block is an incompatible proxy, "
            "never an unstamped response")
    values: Dict[str, Optional[str]] = {}
    for field, key in STAMP_KEY_OF_FIELD.items():
        if key not in block:
            values[field] = None
            continue
        value = block[key]
        if not isinstance(value, str) or not value or value not in STAMP_VOCABULARY[field]:
            raise OutOfSupportAttestationRefusal(
                REC_OOS_SALT_POLICY_UNEXPECTED,
                f"{STAMP_BLOCK_KEY}.{key} = {value!r} ({type(value).__name__}) is present but "
                + ("outside the contract's vocabulary "
                   f"{list(STAMP_VOCABULARY[field])}" if isinstance(value, str) and value else
                   f"not a non-empty string from {list(STAMP_VOCABULARY[field])}")
                + " — a present malformed stamp is an incompatible proxy, never an absent field")
        values[field] = value
    return StampRegimes(**values)


class CellSpellings(NamedTuple):
    """Every spelling of ONE cell at the doors it passes (contract §2.5.2 /
    §2.5.10 Q8's door table): ``traintest`` — the ``--cell`` and
    ``--expect-object-sha256`` key spelling (TrainTest id, plus the variant
    when declared); ``harness`` — the attestation-map key and the registry id
    (the harness id, plus the variant); ``vmodel`` — the virtual model
    (``VMODEL_PREFIX`` + harness); ``expect_key`` — the key of
    ``--expect-object-sha256 <key>=<sha>`` (``None`` = the bare sha, "the
    single fitted cell")."""

    traintest: str
    harness: str
    vmodel: str
    expect_key: Optional[str]


def cell_spellings(cell: str, *, declared: bool) -> CellSpellings:
    """The ONE helper for a cell's spellings at the doors (contract §2.5.2,
    §2.5.10 Q8). The variant is split off FIRST — :func:`parse_launcher_cell`
    refuses ``…@thinking`` — and re-joined at the doors.
    ``declared=False`` on a bare cell returns today's spellings byte for byte
    (``expect_key`` None); ``declared=True`` returns the ``@thinking``
    spellings with ``expect_key`` per :data:`OOS_EXPECT_SHA_KEY`. An id already
    carrying ``@thinking`` is accepted with ``declared=True`` (same result) and
    refused with ``declared=False``; any other variant refuses. Refuses
    ``declared=True`` on the base or a prompted cell (variants are legal on
    OBJECT cells only), and should :data:`OOS_STANDUP_CELL_SUFFIX` /
    :data:`OOS_EXPECT_SHA_KEY` read ``None`` or the suffix not be the
    vocabulary's ``VARIANT_SEP + VARIANT_THINKING`` (a mutated module)."""
    base, variant = _split_variant(cell)
    if variant is not None and variant != VARIANT_THINKING:
        raise CellNameError(
            f"cell {cell!r}: serve variant {variant!r} is not a harness spelling — this harness "
            f"serves the {VARIANT_THINKING!r} variant only (experiment 1); the position variants "
            "are experiment 2's")
    if variant is not None and not declared:
        raise CellNameError(
            f"cell {cell!r} carries the {VARIANT_THINKING!r} serve variant but was passed as "
            "UNDECLARED — the spelling and the flag contradict; pass the bare cell, or declared=True")
    parsed = parse_launcher_cell(base)
    dc, _ra = _cell_grammar()
    # the virtual model through the REGISTRY's own mapping (``defense_cells``'
    # ``virtual_model_name``, the rule ``enumerate_cells`` writes into every
    # route): the base route is served as ``petri__base`` — never
    # ``petri__<cell id>``, which a prefix rule here once produced — and an
    # object or prompted cell as ``petri__<harness id>``
    vmodel_base = str(dc.virtual_model_name(parsed.harness_id))
    if not declared:
        return CellSpellings(traintest=parsed.cell, harness=parsed.harness_id,
                             vmodel=vmodel_base, expect_key=None)
    if parsed.kind != CELL_KIND_FITTED:
        raise CellNameError(
            f"cell {cell!r} ({parsed.kind}) cannot be declared served out of support: a "
            "variant is legal on an OBJECT cell only (contract §2.5.2) — the base route and a "
            "prompted cell serve no fitted object, so there is nothing to declare")
    _reconciled("OOS_STANDUP_CELL_SUFFIX", "OOS_EXPECT_SHA_KEY")
    if OOS_STANDUP_CELL_SUFFIX != VARIANT_SEP + VARIANT_THINKING:
        raise OutOfSupportDeclarationUnreconciled(
            f"OOS_STANDUP_CELL_SUFFIX {OOS_STANDUP_CELL_SUFFIX!r} is not the vocabulary's "
            f"{VARIANT_SEP + VARIANT_THINKING!r} (serve_declaration.VARIANT_SEP + VARIANT_THINKING)")
    if OOS_EXPECT_SHA_KEY not in OOS_EXPECT_SHA_KEYS:
        raise OutOfSupportDeclarationUnreconciled(
            f"OOS_EXPECT_SHA_KEY {OOS_EXPECT_SHA_KEY!r} is not one of {OOS_EXPECT_SHA_KEYS}")
    traintest = _join_variant(parsed.cell, VARIANT_THINKING)
    harness = _join_variant(parsed.harness_id, VARIANT_THINKING)
    expect_key = (traintest if OOS_EXPECT_SHA_KEY == OOS_EXPECT_SHA_KEY_TRAINTEST_VARIANT
                  else None)
    return CellSpellings(traintest=traintest, harness=harness,
                         vmodel=_join_variant(vmodel_base, VARIANT_THINKING), expect_key=expect_key)


def standup_cell_spelling(cell: str, *, declared: bool) -> str:
    """What the launcher's ``_standup_cmd`` passes as ``--cell`` for this
    configuration: :func:`cell_spellings`' ``traintest`` — the variant
    spelling on a declared (thinking-ON, out-of-support, lens) standup only,
    the bare cell everywhere else (S4.4)."""
    return cell_spellings(cell, declared=declared).traintest


