def sandbox_entrypoint(dataset: str, *, parallel: int = SANDBOX_CPU) -> str:
    if dataset not in EVALPLUS_DATASETS:
        raise ControlNameError(f"{dataset!r} is not an evalplus dataset: {list(EVALPLUS_DATASETS)}")
    return SANDBOX_ENTRYPOINT.format(workdir=SANDBOX_WORKDIR, dataset=dataset,
                                     samples=SANDBOX_SAMPLES_PATH, parallel=int(parallel))


