#: S3.4: the measured switch/moves agree with ``/v1/models.petri_proxy.thinking_header``
OOS_EVIDENCE_HEADER_ATTESTED_AGREES = "header_attested_agrees"
OOS_EVIDENCE_ATTESTED_SWITCH = "attested_switch"
OOS_EVIDENCE_ATTESTED_MOVES = "attested_moves"
