OOS_EVIDENCE_BITES_APPLICABLE = "applicable"
OOS_EVIDENCE_BITES_VERIFIED = "verified"
OOS_EVIDENCE_BITES_TWIN = "twin"
OOS_EVIDENCE_BITES_N_DIFFERING = "n_differing"
